INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муруз дар бораи муҳимии оварии чуққора барои ғаллоҳи теритикал</h2>\n<p>Теритикал (Triticale) ҳамчун як ҳосили донаҳои рағбатӣ, омехтаи ғаллоҳи гандум ва яғурк аст, ки аз сабаби таъсири гуногуни он барои озуваи чорво ва инчунин барои пӯшидан хок истифода мешавад. Дар шароити хушксолӣ ва маҳдудии захираҳои об, истифода аз системаҳои оварии зер фишор ва айниқадар <strong>оварии чуққора</strong> ё рибони чип (tape), тағйироти асосиро ба устуворӣ ва самаранокии ниҳоии ин навишот ба вуҷуд меорад. Дар ин қисми дастурҳои муфассал, мо мехоҳем донем, ки чӣ тавр бо омехта намудани асосҳои ғаллоҳ ва идоракунии дақиқи об, ба кӯрҳои теритикали устувор расем. Теритикал аз сабаби доридани решаҳои қавӣ ва ҳиссинокии хушкӣ, интихоби муносиб барои кӯр намудан дар минтақаҳои камоб аст, вале ин муқовимат танҳо вақте ба натиҷа мерасад, ки заминаи муносиби решагиранӣ ва идоракунии дурусти намнокӣ фароҳам оварда шавад.</p>\n\n<h3>Фоидаҳои истифодаи рибони чип (tape) дар теритикал</h3>\n<p>Калонтарин фоидаи оварии чуққора дар теритикал, паҳни якдаст намдани намнокӣ дар муҳити решаҳои навишот аст. Ин навишот ба намнокии даимоми дар сатҳи хок ҳиссиноки дорад; бинобар ин, рибони чип бо эҷод кардани рибони намнок, фишори обӣ-и об (water stress)-ро паст меорад. Гарчанде теритикал як ҳосили кӯрҳои зимистона ва донамонанд ба назар мерасад, ки даромадгирӣ ба системаҳои мураккаб надорад, вале дар истифодаҳо барои озуваи чорво, ки мақсад максимум кардани биомасс аст, оварии чуққора нақши ҳаётӣ дорад. Ин системаҳо бо кам кардани бухоршавӣ ва зиёд кардани самаранокии оварӣ, хароҷоти ниҳоии истеҳсолро паст меоранд. Барои шиносоӣ бо чӣ тавр системаҳои овариро барои маҳсулотҳои гуногун ихтисоскунӣ кунем, метавонед таҳқиқ кунед анбори рибони чип-и оварии чуққорӣ ва роҳи кори онҳо.</p>\n\n\n\n<h2>Асосҳои кӯр намудани теритикал бо системаҳои чуққорӣ</h2>\n<h3>Расидани муносиби бӯғдӯрӣ ба рибони оварӣ</h3>\n<p>Муҳимтарин принсипи ҷаврони тритикале бо системаи нақбандии чанчони, нигоҳ доштани масофаи муайян байни барг ва системаи оборӣ аст. Барг набояд рост бар нӯр нақбандӣ гузорад, зеро шустани муҳим ва тобидани барг метавонад боиси пазшавӣ ё кам шудани таъсири интиқол гардад. Одатан масофаи 10 то 15 сантиметрӣ аз нӯр тавсия дода мешавад. Ин масъала барои ин сабаб муҳим аст, ки тритикале, ба хотири доридани рӯбҳои хурд ва васеъ, ҳассос ба тақсимоти мунтазами намнокӣ мебошад. Риояи ин масофа боиси мегардад, ки рӯбҳо ба намнокӣ саммуд гардайд ва пӯшиши рӯбҳо дар фазои байни хатҳо беҳтар шавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-تریتیکاله-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="راهنمای جامع کاشت تریتیکاله با آبیاری قطره‌ای - تصویر 1"/><figcaption>тарҳҳои ҷаврони тритикале нақбандии чанчони барои обори ҷавр</figcaption></figure>\n\n<h3>Зичии ҷаврон дар шароити нақбандии чанчони</h3>\n<p>Бинобар доридани харҷи аввалии баландтар аз тарафи системаҳои нақбандии чанчони, зичии барг метавонад каме чарогиштар бошад. Аммо, зичии стандартии тритикале одатан байни 150 то 200 килограмм дар гектар аст. Дар минтаҳое, ки борон доидаш карда шавад, метавон заҳомро кам кард, то рақиби байни бутаҳо камтар шавад. Ин ба принсипҳои ҷаврони дигар гиёҳҳои сабз ва пӯшишбахш монанд аст; масалан дар <a href="https://navar-abyari.ir/%D9%85%DB%8C%D8%B2%D8%A7%D9%86-%D8%A8%D8%B1%D8%AF%D8%A7%D8%B4%D8%AA-%D9%81%D9%84%D9%81%D9%84-%D8%AF%D9%84%D9%85%D9%87-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">Қолиди фалфели дилма дар ҳар гектар</a> замони зичи, инчунин ба қири оборӣ вобаста аст. Дар тритикале, агар ҳадаф истеҳсоли сабзӣ бошад, масофаи байни хатҳо бояд камтар бошад, то пӯшиши хок зиёд гардад. Дар навбат, барои истеҳсоли дон, масофаи зиёдтар барои оғозни пурраи донҳо талаб мекунад.</p>\n\n<h2>Барномаи таъмини замон барои ҷаврони тритикале бо чанчони</h2>\n<h3>Муайян кардани вақти кушодиш дар асоси минтаҳо</h3>\n<p>Тритикала маҳсули охирҳои баҳор аст. Вақти муносиби коркунии тритикала ба минтакаи ҷуғрофӣ вобаста аст. Дар минтаҳои сард, коркунӣ бояд таваҷҷуҳи аввал (оғози моҳи октябр) анҷом шавад, то ки рӯян имконият дошта бошад, ки пеш аз сардӣ решаҳои қавӣ пайдо кунад. Дар минтаҳои нимхушк, ки ба об омадани тамға вобаста аст, коркунӣ метавонад каме дертар анҷом шавад. Нуқтаи муҳим ин аст, ки пеш аз коркунӣ, системаи обкунӣ бояд пурра тайёр бошад ва санҷиши дагмарзан анҷом дода шавад. Илова бар ин, баданро бояд аз ҷиҳати сифат ва қувваи инкубацӣ (зӯри зиндагии бадан) санҷид, то камбогарии якнави ҳосилот боварӣ дошт. </p>\n\n<h3>Ҳисобкунӣ оид ба вақти обкунӣ пас аз коркунӣ</h3>\n<p>Барои тритикала, баръакси чанде аз решаҳои боғдорӣ, ки ба обкунии такрорӣ ниёз доранд, нақшаи обкунӣ бояд бо рушди рӯяни мувофиқат кунад. Дар марҳалаи инкубацӣ, обкунии сабук ва такрорӣ ҳаётии аст. Пас аз он, фосилаи байни обкунӣ бо рушди рӯяни зиёд мешавад. Барои идоракунии беҳтари обҳои зери замин ва шиносиши амиқтари ниёзҳои обии маҳсулоти дондор, омӯзиш дар бораи <a href="https://navar-abyari.ir/barley-yield-per-hectare-factors-increase/">Иқлимноишдани гандум ба ҳектар</a> мехоҳад, зеро тритикала аз ҷиҳати физиологии ба гандум монандии зиёд дорад. Дарсҳои обкунӣ бояд бо барқароркунии мувозинати об замин танзим шаванд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-تریتیکاله-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="راهنمای جامع کاشت تریتیکاله با آبیاری قطره‌ای - تصویر 2"/><figcaption>рӯҳсатҳои коркунӣ тамға кроп обкунӣ нақшаи тритикала</figcaption></figure>\n\n\n<h2>Нуқтаҳои амалӣ дар иҷрои системаи об омадани тамға тритикала</h2>\n<h3>омодагӣ ба бодаҳои бадан ва лӯбикашӣ</h3>\n<ol>\n<li>Земя бояд пурқувват ва коҳистонӣ бошад. Мавҷудияти кӯҳҳои калон ба пайвастшавии якхелаи риштаи тамға ба пошти баргдоҳист барои тоҷрибонишдаҳо.</li>\n<li>Риштаи тамға ё риштаи қатракунак бояд бо баландии муносиби ғайрилозим борӣ. Ин системаҳо одатан дар зери замин (зери замин) ё дар рӯи замин (сатҳӣ) истифода мешаванд. Намуди сатҳӣ барои триккалэ маъмултар аст.</li>\n<li>Дар ниҳолгузории система пеш аз баргирии баргҳо, барои пешгирии вайроншавии қатракунакҳо бо пичи коркард зарур аст.</li>\n</ol>\n\n<h3>Мушкилоти маъмул ва ҳаллаҳо</h3>\n<p>Яке аз мушкилоти маъмул дар баргирии триккалэ бо қатракунак, <strong>Гузариши ришта</strong> ки боиси пайдоишудани минтақаҳои пурҳаҷм ва минтақаҳои камҳаҷм дар решаҳо мегардад. Агар минтақаҳои пурҳаҷм дид шуданд, эҳтимолан ришта аз кӯҳҳои сахт гузашта ва фишори иловагӣ ба он ворид шудааст. Инчунин, истифодаи риштаи тамғаи собит метавонад дар тӯли вақти тӯлонӣ мушкилоти басташавиро нест кунад. Барои пешгирии ин мушкилҳо, беҳтар аст, ки аз <a href="https://navar-abyari.ir/%d9%86%d9%88%d8%a7%d8%b1-%d8%aa%db%8c%d9%be-%d8%ab%d8%a7%d8%a8%d8%aa-fixed-spray-tape/">риштаи тамғаи собит (Fixed Spray Tape)</a> Истифода кунед, ки он ҳолати шустан ва таъмиронишоданиро дорад. Иловаҷон риояи қайдҳои нигоҳубинии риштаи тамғадор пеш аз насб дар майдони саҳроӣ барои таъмини кори система зарурӣ аст; таҳқиқи мақолаҳои алоқаманд монанди <a href="https://navar-abyari.ir/%D9%86%DA%A9%D8%A7%D8%AA-%D9%85%D9%87%D9%85-%D9%82%D8%A8%D9%84-%D8%A7%D8%B2-%D9%86%D8%B5%D8%A8-%D9%86%D9%88%D8%A7%D8%B1-%D8%AA%DB%8C%D9%BE-%D8%AF%D8%B1-%D9%85%D8%B2%D8%B1%D8%B9%D9%87/">Нуқтаҳои муҳим пеш аз насби риштаи тамғадор дар майдони саҳроӣ</a> тавсия карда мешавад. Ин нуқтаҳо баррасии фишори об, сифати филтрсиян ва санҷиши ибтидоии системаро дар бар мегирад.</p>\n\n\n\n<h2>Саволҳои маъмул дар бораи тритикале ва обориши тамъадӣ (бӯрида)</h2>\n<p><strong>Оё тритикале барои обориши тамъадӣ (бӯрида) мувофиқ аст?</strong><br>Бале, махсусан ҳангоме, ки мақсади истеҳсоли сабзавот барои чорвододорӣ бошад. Обориши тамъадӣ (бӯрида) истеҳсоли якҷоя бо камтарин ҳарозӣи обро ба вуҷуд меорад.</p>\n<p><strong>Оё бояд ба риштаи тамғадор моддаҳои кимиёвӣи иловагӣ зарб дода шавад?</strong><br>Не, барои тритикале лозимоти фитоник вуҷуд надорад. Риштаи обориш ва фазои бақаро барои идоракунии об кофӣ аст.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-تریتیکاله-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="راهنمای جامع کاشت تریتیکاله با آبیاری قطره‌ای - تصویر 3"/><figcaption>услуҳи ғардонӣ, барномаи обороӣ пурдонии маҳсулоти триксикале</figcaption></figure>\n<p><strong>Зичии ғӯдаи триксикале бо усули пурдонӣ чӣ қадар аст?</strong><br>Тақрибан 180 кг дар гектар бо фосилаи сатҳҳои 15 см.</p>\n\n<h2>Хулоса ва дидгоҳ дар оянда</h2>\n<p>Ғардониши триксикале бо системаҳои обороии пурдонӣ ва нӯлӣ-теп як услуби устувор ва арзон дар муддати тӯлонӣ аст, ки ба деҳқон имкон медиҳад аз об, ғӯда ва заҳрҳое самараноктар истифода барад. Бо назардошти он, ки триксикале маҳсулоти моқом ба хушкӣ ва камбуди ғизоӣ аст, пайвасти он бо технологияи пурдонӣ метавонад самароро дар минтақаҳои нимхушк афзун кунад. Тавсияи ниҳоӣ ин аст, ки пеш аз ғардонӣ, таҳлилҳои дақиқ аз заҳматкунандаи замин анҷом дода шавад, то боварӣ пайдо карда шавад, ки заминаи ғӯда солим аст. Барои муқоиса бо дигар маҳсулоти кишоварзӣ, таҳқиқ <a href="https://navar-abyari.ir/%d9%85%d9%82%d8%af%d8%a7%d8%b1-%d8%a8%d8%b0%d8%b1-%d8%b2%d8%b9%d9%81%d8%b1%d8%a7%d9%86-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Микдори ғӯдаи зафарон дар гектар</a> нишон медиҳад, ки чӣ гуна интихоби дурусти системаи обороӣ метавонад тафовути калонро дар сифат ва миқдори маҳсулот ба вуҷуд орад. Ин масъалаи муҳимияти интихоби дурусти задири заминро низ равшан мекунад.</p>','Комил дастураб кортиби тритикали бо нақли об тачангӣ: принсипҳо, замонкунонии ва нуқтаҳои амалӣ','Тритикале як афлои бисёрвазории барҷаста мебошад, ки идоракунии дурусти он, махсусан тавассути ободории қатқотӣ, метавонад самаранокии заминро ба таври зиёд таъмин намояд. Ин мақолаи мукаммал, бо такя ба принсипҳои техникии, роҳнамоии дақиқи гирифт ва ободории тритикалеро пешниҳод мекунад, то ки деҳқонон аз тамоми имкониятҳои ин маҳсулот истифода баранд.','publish','closed','closed','dastur-triticale-naqli-ob-tachangi',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
