INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддама дар бораи аҳамияти дақиқӣ дар партов кардани баклаҷон</h2>\n<p>Баклаҷон яке аз маъмултарин ва дӯстдоштагитарин сабзиёти бозорҳои дохилӣ ва содиротӣ аст. Интихоб ва партов кардани дурусти ин набатиёт мустақиман ба сифати маҳсулот, ҳаҷми ҷамъоварӣ ва дар ниҳоят даромади деҳқон таъсир мерасонад. Яке аз муҳимтарин қисмҳои барномарезии пеш аз партоб, муайян кардани <strong>миқдори беоки баклаҷон дар як гектар</strong> ааст. Бисёре аз истеҳсокчиён, бо вуҷуди обёрӣи мувофиқ, аз сабаби зичии номувофиқ ё сарфнокии беоки натиҷаҳои хуб ба даст наомадаанд. Дар ин дасторон мо ниёти дорем, бо такя ба принсипҳои агрономия ва таҷрибаҳои амалӣ, ба шумо кӯмак расонем, то беҳтарин зичии партовро бар асоси навъи беоки (голландӣ ё эронӣ) ва шароити заминаи худ муайян кунед.</p>\n<h3>Чаро ҳисобкунии дақиқи зичии партоб муҳим аст?</h3>\n<p>Зичии партоб ё Seed Rate ба шумори набототи зинда дар воҳиди сатҳ (гектар) ишора мекунад. Агар зичӣ аз ҳад зиёд баланд бошад, набототҳо барои дастрасӣ ба рушноӣ ва моддаҳои ғизоӣ бо ҳамдигар рақобат мекунанд, ки боиси хурд шудани беоки ва паст шудани сифат мегардад. Аз ҷанби дигар, зичии паст боиси парвариш зиёди ҳашарот ва кам шудани самаранокии иқтисодии замин мегардад. Бинобар ин, ёфтани нуқтаи мувозинат байни шумори наҳолҳо ва фазои зарурӣ барои онҳо, калиди муваффақият аст. Дар ин роҳ, фаҳмидани робита байни чуқурии беоки ва <a href=\'https://navar-abyari.ir/%d9%85%db%8c%d8%b2%d8%a7%d9%86-%d8%a8%d8%b1%d8%af%d8%a7%d8%b4%d8%aa-%d8%b1%db%8c%d8%ad%d8%a7%d9%86-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/\'>миқдори ҳошиш ҷамъоварандашуда дар як гектар</a> метавонад намунаеро барои сабзиёти бо афзоиши монан пешкаш кунад, гарчанде бахлатҷон аз сабаби давраи дарозтари афзоиш, ба идоракунии гуногун ниёз дорад.</p>\n\n[3]]</strong> Дар ин қисми мета, агар ба назар расад, ки бояди аз сабаби хатои чопӣ дар коди пештар ислоҳ шавад, аммо мувофиқи дастурамал ман бояд аз ишораҳо истифода барам. Биёед онро ислоҳ кунем, то сохтори дуруст бошад.\n\n<h2>Омилҳои муайянкунандаи миқдори бадони боднҷон дар як гектар</h2>\n<p>Барои ҳисобкунии дақиқи миқдори бадони зарурӣ, бояд чанд тағйирёбандаи асосиро ба назар гиред. Ин тағйирёбандаҳо намуди бадон, шароити иқлимии минтақа, системаи оборӣ ва намуди хуравро дар бар мегиранд.</p>\n<h3>Намуди бадон ва вазни ҳазор дона (Вазни ҳазор дона)</h3>\n<p>Бадонони боднҷон ба ду гурӯҳи умумӣ ҷудодастӣ мешаванд: бадонони ошкорполизшуда (Open Pollinated) ва бадонони гибридӣ. Бадонони гибридӣ одатан суръати ғунбадофтанро баландтар доранд, аммо хароҷоти зиёдтарро низ доранд. Вазни ҳазор донаи боднҷон тағйирёбанда аст; вобаста ба арзҳои гуногун, ин вазн метавонад аз 25 то 55 грамм тағйир кунад. Ҳар қадаре вазни ҳазор дона камтар бошад, шумо ба шуми бештари дона барои ташкили як ниҳол ниёз доред. Бинобар ин, ҳисобкунии <strong>миқдори бадони боднҷон дар як гектар</strong> бе донистани вазни донаҳои мушахх, ки харидордаед, ғайриимкон аст. Тавсия мекунем, ки пеш аз хариди бадон, барқарораки пас аз қутбиро санҷед, то аз фоизи нокифоя ва вазни дона огоҳ шавед.</p>\n<h3>Фосилаҳои стандартии насб</h3>\n<p>Фосила байни сатҳҳо ва фосила байни ҷамъиятҳо (нуқтаҳои кундан) таъсири мустақимро ба шумораи дарахтон дар ҳектар ва дар натиҷа ба миқдори бехи истифодашуда меорад. Ба умумият, фосилаи байни сатҳҳои бадун одатан байни 60 то 90 сантиметр ва фосилаи байни дарахтоён дар сатҳ 40 то 60 сантиметр аст. Барои намудҳои пурмаҳсул ва шохадор тавсия мешавад, ки фосилаҳои бештар истифода шаванд, то ки ба гиёҳ имкон дод шавад, ки нафас гирад ва бемориҳои қамчӣ кам шаванд.</p>\n<ul>\n<li>Фосилаи байни сатҳҳо: 60 сантиметр (барои киштҳои зичтар)</li>\n<li>Фосилаи байни дарахтоён: 50 сантиметр (стандарти умумӣ)</li>\n<li>Чоидагирии кундани бех: 1 то 1.5 сантиметр</li>\n</ul>\n\n[3]]</strong> Ин нишона бояд ислоҳ шавад. Биёед аз нишонҳои муайяншуда дар промпт истифода барем: , , .\n\n<h2>Формулаи ҳисобкунӣ ва ҷадвали дастурамон</h2>\n<p>Барои он ки шумо тавонед амалӣ <strong>Миқдори бехи бадун дар ҳектар</strong> барои ҳисоб кардан, аз марҳилаҳои зерин истифода баред. Ин формулаҳо бар асоси таҷҳизоти ҳоҷат ва парҳези ратсионалӣ сохта шудаанд.</p>\n<h3>Марҳилаҳои ҳисобкунии қадам ба қадам</h3>\n<ol>\n<li>Ҳисоб кардани шумораи нахиҳои лозима дар ҳектар дар асоси масофаи миёнаи байни кӯмакҳо. Формулаи оддӣ: Шумораи нахиҳо = (10000 метр мураббаъ / (масофаи сутунҳо бо метр × масофаи кӯмакҳо бо метр)).</li>\n<li>Муайян кардани сурати нопокии бодар ва сурати нашвакшавӣ. Одатан, барои бодарҳои тоза, сурати нашвакшавии 95% қабул карда мешавад. Бинобар ин, миқдори воқеии бодарро ба 95% тақсим кунед.</li>\n<li>Ҳисоб кардани вазни ниҳоии бодар дар назар доштани вазни ҳазор дана. Вазни дана = (шумораи данаҳои лозима / 1000) × вазни ҳазор дана (барои ҳар килограмм).</li>\n</ol>\n\n<p>Дар поён ҷадвали миқдори тахминии бодари лозима барои масофаҳои маъмул оварда шудааст. Ин рақамҳо дар асоси вазни ҳазор дана 40 грамми ва сурати нашвакшавии 95% ҳисоб шудаанд ва танҳо роҳнамои умумӣ мебошанд:</p>\n<table border="1" cellpadding="5" cellspacing="0" style="width:100%; border-collapse: collapse;">\n<thead>\n<tr>\n<th style="text-align: left; padding: 10px;">Масофаи миёнаи сутунҳо (метр)</th>\n<th style="text-align: left; padding: 10px;">Масофаи миёнаи кӯмакҳо (метр)</th>\n<th style="text-align: left; padding: 10px;">Шумораи ниҳол дар ҳектар (тахминӣ)</th>\n<th style="text-align: left; padding: 10px;">Миқдори лозимаи тоҳук (килограмм)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td style="padding: 10px;">0.6</td>\n<td style="padding: 10px;">0.5</td>\n<td style="padding: 10px;">33,333</td>\n<td style="padding: 10px;">аз 1.4 то 1.5</td>\n</tr>\n<tr>\n<td style="padding: 10px;">0.7</td>\n<td style="padding: 10px;">0.5</td>\n<td style="padding: 10px;">28,571</td>\n<td style="padding: 10px;">1.2 то 1.3</td>\n</tr>\n<tr>\n<td style="padding: 10px;">0.8</td>\n<td style="padding: 10px;">0.6</td>\n<td style="padding: 10px;">20,833</td>\n<td style="padding: 10px;">0.9 то 1.0</td>\n</tr>\n</tbody>\n</table>\n\n<p>Диққат диҳед, ки ин рақамҳо тахминӣ мебошанд ва бояд барои мувофиқат бо шароити замин танзим карда шаванд. Агар шумо аз системаҳои jackseeding (бо муҳаррик нонӣ каторӣ) истифода баред, дақиқияти каратонӣ баландтар аст ва лозимияти насбӣ камтар мешавад. Аз тарафи дигар, дар карати дастӣ, ҳамчон таъмини зарурӣ 10 то 20% миқдори зиёди тухмро дар назар гиред, то дар сурати лозим ивазҳои j-powder иҷро шаванд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-بادمجان-در-هکتار-راهنمای-جامع-تصویر-شاخص.webp" alt="مقدار بذر بادمجان در هکتار: راهنمای جامع - تصویر 1"/><figcaption>seed rate per hectare crop баклажан</figcaption></figure>\n\n[3]]</strong> Биёед нишондиҳандаи моро дуруст иҷро кунем. Дар куҷои ин бояд ҷойгир шавад.</p>\n<p>Дар тасвири поён фарқияти зоҳирӣ байни ғалғотии баланд ва муносибатии маъмулро мебинед. Галғотии баланд одатан боиси таркиби хӯрокӣ ва меваҳои хурдтар мешавад.</p>\n[IMAGE_2]</strong> Меро бояд аз нақари синтаксиси JSON дуруст кунам, зеро ман дар маркази таваҷҷуҳи пепти мефаҳмам. Биёед натиҷаи ниҳоиро бо диққат сохт.</p>\n\n[2]] ва [3]]-ро дар ҷои мувофиқ гузорем.</p>\n<p>Таҷриба нишон дод, ки дар шимони кишвар, ба сабаби нимадории баланд ва эҳтимоли афзудаги бемориҳои вирусӣ, беҳтар аст, ки аз галғотии пасттар ва фосилаҳои бештар истифода кунед. Ин масъала ба идоракунии ғалғотии сабзавотҳои дигар хеле монанд аст. Барои муқоиса, метавонед миқдори дони три-тикла дар гектарро низ дида, дидгоҳи васеътарро барои идоракунии таносуб дар муқобили расмҳо дошта бошед.</p>\n\n[3]]</strong> Ин нишондиҳандаҳо бояд дақиқан ба шакли бошанд. Биёед идома диҳам.</p>\n<h2>Нуктаҳои амали барои беҳтар кардани ғалғотии талғизия</h2>\n<p>Таҳияи дон танҳо маънои истифодаи камакнори онро надорад, балки маънои истифодаи ҳадд зиёдеро барои ҳар дони донро дорад. Дар ин ҷо чанд нуктаи асосӣ барои беҳтар кардан <strong>Миқдори бӯди бӯди ғалка барои як гектар</strong> Машхут аст:</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-بادمجان-در-هکتار-راهنمای-جامع-کاربرد-عملی.webp" alt="مقدار بذر بادمجان در هکتار: راهنمای جامع - تصویر 2"/><figcaption>Нисбати бӯди барои ҳектари ғалка</figcaption></figure>\n<ul>\n<li><strong>Омодагӣ додани бӯдӣ:</strong> Пеш аз корбидан, бӯдиро бо консентратсияи пасти кислотаи пектои потассий ё оби гарм (50 дараҷа) шуста то қабуди он нарм шавад ва афкундашавӣ якхела бошад. Ин кор метавонад суръати афкундашавиро то 15% зиёд кунад ва таваққуфи бӯдиро коҳиш диҳад.</li>\n<li><strong>Интихоби хонаи шишагии мувофиқ:</strong> Агар аз нармашаклҳои хонаи шишагӣ истифода баред, ҳеҷ гуна ҳисоби бӯдӣ барои карботи аввалин лозим нест, аммо бояд таъмини нармашаклҳои солим ва озод аз афатҳо бошад. Дар ҳолати истифодаи бӯдӣ, ҳарорати хонаи шишагӣ бояд аз 25 то 30 дараҷаи Селсий бошад.</li>\n<li><strong>Идоракунии обёривии аввалин:</strong> Оборои ғарқобӣ дар ҳафтаҳои аввали баъд аз калонкунӣ метавонад боиси қатигии данаҳо ва коҳиши рӯшанӣ гардад. истифодаи <a href=\'https://navar-abyari.ir/%D9%86%D9%88%D8%A7%D8%B1-%D8%A2%D8%A8%DB%8C%D8%A7%D8%B1%DB%8C-%D8%A8%D8%B1%D8%A7%DB%8C-%DA%A9%D8%AF%D9%88/\'>обори риштавӣ барои бодиринг</a> ҳамчун намуна барои системаҳои камсарф оварда ба назар расидан мумкин аст, зеро бобат (бадмитзан) низ ба обори қатрагорӣ ҳассос аст. Обори қатрагорӣ таъмин мекунад, ки намии хок якхела боқӣ монад ва рӯшани беҳтар ба вуҷуд орад.</li>\n</ul>\n\n[2]]</strong> Биёед нишондиҳандаҳоро دقیق ҷое гузорем, ки лозим аст.</p>\n<p>Яке аз хатоҳои маъмул, калон кардани данаҳо дар чуқурӣ аст. Данаҳои бобат (бадмитзан) хеле хурданд ва агар чуқур калон карда шаванд, қувваи кофӣ бар бардоштани сатҳи хок надоранд. ҳамеша чуқурии калонкуниро байни 1 то 1.5 сантиметр нигоҳ доред. инчунин, омезиш додани данаҳои наворҳои гуногунро дар як гӯлдон пайдо накунед, зеро намунаи рӯшанӣ ва буҳорашон гуногун хоҳад буд.</p>\n\n[1]]</strong> Ин нишондиҳанда бояд дар оғоз ё анҷоми як қисм бошад. Биёед сохторро якҷоя кунем.</p>\n<h2>Таъсири системаи оборишавӣ ба зичӣ ва данаҳо</h2>\n<p>Системаи оборишавӣ, омили пинҳон, аммо хеле муҳим дар муайян кардани <strong>Микдори боби бодирӣ ба ҳектар</strong> аст. Дар шароити хушк ва камбораён, истифодаи системаҳои қаътарӣ бо суръати паст (2 то 4 литр дар соат) имкони идоракунии дақиқтари тарроҳро медиҳад. Ин назорати дақиқ ба шумо имкон медиҳад, ки аз зичии мувозинатшуда истифода баред, зеро наботот стресси камтари тарроҳро ҳис мекунанд.</p>\n<p>Баръакс, агар аз системаҳои анъанавии оборӣ, ба монанди обории харосбӣ истифода кунед, тағйирёбии тарроҳ боиси мешавад, ки қисме аз наботот суст ва қисми дигар тез растанд. Ин нобаробарӣ одатан ба зичии балдатар ниёз дорад, то зарари баҳос аз замин хушк ҷуброни шавад, ки дар охир боиси пардохтшавии манбаъҳои боб мебошад. Бинобар ин, гузаштан ба системаҳои муосиртара метавонад бевосита ба миқдори боби истеъмолшаванда ва маблағи умумии намудгузорӣ таъсиранд.</p>\n\n[3]]</strong> Марзакораи охиринро дар ҷо ҷойгир кунем.</p>\n<h2>Саволҳои маъмулӣ (FAQ)</h2>\n<p><strong>1. Оё бобҳои хибридӣ ва маҳаллӣ дар миқдори истеъмол фарқ доранд?</strong><br>\nБале, бобҳои хибридӣ одатан суръати баландтари шуруъи растанӣ доранд ва метавонед ба миқдори камтари боб ниёз дошта бошед, вале ҳассосияти баландтар ба шароити муҳит доранд. Бобҳои маҳаллӣ анъанавӣ бисёрнишонагӣ доранд ва дар шароити нохуш бештар давом меоранд, вале барои пӯшиди пурра метавонанд ба миқдори бештари боб ниёз дошта бошанд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-بادمجان-در-هکتار-راهنمای-جامع-جزئیات-فنی.webp" alt="مقدار بذر بادمجان در هکتار: راهنمای جامع - تصویر 3"/><figcaption>normi bobi ba gektar mevol bodiriy</figcaption></figure>\n<p><strong>2. Беҳтарин вақти коркардани бӯнгит дар минтақаҳои гуногуни Эрон чист?</strong><br>\nДар минтақаҳои хунук, бӯнҳо бабораҳ (аз апрел то май) коркарда мешаванд ва дар минтақаҳои гарм, коркаши ташрихӣ (аз сентябр то октябр) маъмул аст. Арзиши ҳарорати об барои рӯйдидан бояд аз 15 дараҷаи Селсий боло бошад.</p>\n<p><strong>3. Чӣ тавр метавонам аз талафоти бӯн пешгирӣ кунам?</strong><br>\nИстифодаи заминаҳои коркард (палет ё пад), идоракунии дақиқинам ва интихоби бӯнҳои бо арзиши беҳтар аз ширкатҳои маъруф, муҳимтарин омили кам кардани талафот аст. Инчунин, нигоҳдорӣ бӯнро дар ҷои хунук ва хушк пеш аз коркард, тозагии онро нигоҳ медорад.</p>\n\n[3]]</strong> Ин нишондиҳандаро бояд фақат як маротиба дар матни кӯл истифода барам. Биёед сохтори ниҳоии JSON-ро бисозем.</p>\n<h2>Хулоса</h2>\n<p>Таҳлил <strong>Мадори бӯн бӯнгит дар ҳектар</strong> Ин раванди дақиқ аст, ки эҳтиром ба тафсилотро талаб мекунад. Аз интихоби навигарони мувофиқ то ҳисобкунии фосилаҳои кӯронокӣ ва системаи обёрӣ, ҳар як омил нақши худро дар муайян кардани поёнии хароҷот ва самарамандӣ иҷро мекунад. Бо истифода аз формулаҳое, ки дар ин мақола пешниҳод шудаанд, ва диққат ба шартҳои махсуси замини худ, шумо метавонед миқдори беҳтарини баргзориро истеъмол намуда, дар айни ҳол сифат ва миқдори маҳсулоти худро зиёд кунед. Фаромӯш накунед, ки замини шумо ягона аст ва ҳеҷ рақами умумие вуҷуд надорад, ки барои ҳамаи заминҳо дуруст бошад; санҷиш ва ченкушӣ, калиди осеби шумост.</p>\n<p>Барои омӯзиши бештар дар бораи сабзавотҳои дигар ва идоракунии ҳаҷм, шумо метавонед ба мақолаи «Миқдори барги янҷуи Хамдани дар гектар» муроҷиат кунед, ки тақрибан монанди идоракунии сабзавотҳои баргдор аст.</p>\n\n<p><strong>Маводҳои вобаста:</strong> <a href="https://navar-abyari.ir/%d9%85%d9%82%d8%af%d8%a7%d8%b1-%d8%a8%d8%b0%d8%b1-%db%8c%d9%88%d9%86%d8%ac%d9%87-%d9%87%d9%85%d8%af%d8%a7%d9%86%db%8c-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Миқдори барги янҷуи Хамдани дар гектар + омили таъсиррасонанда</a>， <a href="https://navar-abyari.ir/%D9%86%D9%88%D8%A7%D8%B1-%D8%AA%DB%8C%D9%BE-%D8%A8%D8%B1%D8%A7%DB%8C-%D9%84%D9%88%D8%A8%DB%8C%D8%A7/">D986D988D8A7D8B1 D8AADB8CD9BE D8A8D8B1D8A7DB8C D984D988D8A8DB8CD8A7</a></p>','Миқдори тоҳи бодирим дар як гектар: Раҳнамои ҷамъбасти комил','Оё медоед, ки барои як гектар беҳмол чанд килограмм ҷурӯъ лозим аст? Дар ин мақолаи фаровоне, формулаҳо барои ҳисоб кардани зичии боркунӣ, масофаҳои мувофиқ ва нуқтаҳои асосиро барои бозомонӣ истинод ҷурӯъро бо дақиқӣ таҳқиқ мекунем, то ки натиҷаи бодиҳои шумо ба ҳадди асосӣ расад.','publish','closed','closed','miqdori-tohi-bodirim-dar-yak-gektar',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
