INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаррада: Аҳамияти муайян кардани дақиқи миқдори беҳи ройха</h2><p>Ройха яке аз гиёҳҳои доруӣ ва зинатии маъмул аст, ки дар бозорҳои дохилӣ ва хориҷӣ талаботи баланд дорад. Барои парвариши муваффақи ин гиёҳ, донистани <strong>миқдори беҳи ройха дар ҳектар</strong> аввалин ва муҳимтарин қадам аст. Бисёр деҳқонони наврас фикр мекунанд, ки ҳар қадар беҳи бештар кор андозанд, ҳосили зиёдтар ҳосил мекунанд, аммо ин бовари нодуруст метавонад боиси рақобат байни гиёҳҳо, афзоиши заиф ва зиёд шудани арзишҳои истеҳсолот гардад. Муайян кардани дақиқи гъамият на танҳо боиси кам шудани хароҷоти беҳ мегардад, балки тавассути фароҳам овардани фазои кофӣ барои афзоиши рӯйи ва қаби, сифати ниҳоии баргҳоро низ беҳтар месозад. Дар ин дастур мо аз ҳисобҳои асосӣ то танзими обёркунӣ бо таври қатора ва навигрии типро барои беҳтар кардани парвариши ройҳа мавриди баррасӣ мегирем.</p><h3>Чаро фосилаи корандозии ройха муҳим аст?</h3><p>Ройҳа гиёҳест, ки барои шакл гирифтан ба равшанӣ ва ҳавои мувофиқ ниёз дорад. Агар фосилаи байни гиёҳҳо хеле кӯтоҳ бошад, сояи як гиёҳ ба дигар боиси этилётсия (Etiolation) мегардад ва гиёҳҳо дароз ва нозук бо бофти заиф меафзоянд. Аз тарафи дигар, агар фосила хеле вазъ бошад, майдони зарарбахш ба хуб пӯшида намешавад ва овуҷҳои нолаззат имконият пайдо мекунанд, ки меафзоянд. Аз ин рӯ, мувозинат дар ҳисоб кардани миқдори беҳ дар ҳар воҳиди масоҳат калиди муваффақият аст.</p><p></p><h2>Ҳисобҳои асосӣ барои муайян кардани миқдори беҳи ройха дар ҳектар</h2><p>Барои он ки бидонед, дақиқан чӣ қадар беҳ лозим аст, бояд аз формулаҳои стандартии кишоварӣ истифода баред. Ин ҳисобҳо вобаста ба нави парвариш (замин ё хак) ва андозаи кӯрпӯшҳо тағйир меёбанд. Дар таҳлула, беҳи ройха хеле майда аст ва вазнааш кам мебошад. Одатан, байни 3 то 5 килограмм беҳ дар ҳар ҳектар тавсия дода мешавад, аммо ин рақам тағйирот пайдо мекунад.</p><h3>Стандарти ғамори кунӣ (Танорафии майдонӣ)</h3><p>Дар меҳвари деҳотӣ дар майдони озод, масофаҳои зерин тавсия шудаанд, ки тавассути онҳо метавонед миқдори бугдуми риҳанро дар ҳектар ҳисоб кунед:</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-ریحان-در-هکتار-راهنمای-جامع-تصویر-شاخص.webp" alt="مقدار بذر ریحان در هکتار: راهنمای جامع - تصویر 1"/><figcaption>Муқовимати бугдуми ҳар ҳектар кунӣ риҳан</figcaption></figure><ul><li><strong>Масофа байни сатрҳо (Сатр ба сатр):</strong> 40 то 50 сантиметр. Ин масофа барои трафик чароғӣ ва дастрасӣ ба ғамор мувофיק аст.</li><li><strong>Масофа байни бугдумҳо (Бугдум ба бугдум):</strong> 20 то 25 сантиметр. Ин масофа ба ғаморҳои конусӣ имконият медиҳад, ки дар кунҷҳои зебоӣ ва иқтисодӣ мусоид бошанд.</li></ul><p>Бо татбиқ кардани ин масофаҳо, шуми бугдумҳои тахминӣ дар ҳар ҳектар тақрибан 80,000 то 100,000 бугдум хоҳад буд. Бо фарзияи мукамматнокии 15 то 20 фоизи гум шудани бугдум ва пурра наофтодани он, шумо ба тақрибан 4 килограмми бугдуми сифатнок дар ҳар ҳектар ниёз доред.</p><h3>Корт ба сепҳо ва кортҳои марказнок</h3><p>Дар корт ба сепҳо, идоракунии манбаъҳо душвортар аст ва фазо камтар аст. Дар ҳолати мазкур, метавон масофаҳои кӯтоҳтарро истифода бур, вале бояд диққат ба ҳавошударии мувофиқи фазои сабз буд. Истифодаи бобҳои гибридӣ ё таҳлиҳшуда метавонад ба кам кардани миқдори боби истифодашуда кӯмак расонад, зеро ҳаҷми булудани онҳо баландтар аст. Дар ин бахш, ишора ба <a href="https://navar-abyari.ir/musir-seed-per-hectare-yield-increase/">Афзоиши ҳосилот тавассути интихоби боби мувофиқ</a> муфид аст, зеро принсипҳои интихоби боб барои реҳун низ монанди дигар набототи сабзсобиҳо аст.</p><p></p><h2>Нақши обёрӣ бо тамасиқ ва наварии тип дар идоракунии боб ва рушд</h2><p>Обёрӣ омилест, ки на танҳо баъд аз парҳезкунӣ муҳим шуда, балки аз лаҳзаи парҳези боб оғоз меёбад. Истифодаи системаҳои обёрӣ зери фишор, ба монанди тамасиқ ва наварии тип, назорати дақиқи намро таъмин мекунад, ки ба таври мустақим ба якхелагии булудани боби реҳун дар гектар таъсир мерасонад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-ریحان-در-هکتار-راهنمای-جامع-کاربرد-عملی.webp" alt="مقدار بذر ریحان در هکتار: راهنمای جامع - تصویر 2"/><figcaption>seed rate per hectare crop Рӣҳун</figcaption></figure><h3>Таъсири намдории якхела ба ҳаҷми ҳосил</h3><p>Агар оборунии галлӣ (Flood) анҷом дода шавад, бубҳои хурди ригони метавонанд дар қабли гуногуни хок нишастан, ки сабаби номуайянии паҳши растаниҳо мегардад. Аммо бо <strong>обориши поқатӣ</strong>намнокӣ дар радиуси муайян аз ҷузъҳои реша ташкил меёбад. Ин ҳолат боиси ин шуда, ки растаниҳо дар фосилаҳои муайяншуда ба хуб шакл гиранд ва рақобат барои об кам шавад. Дар воқеъ, системаи обориш бояд чунин тарҳрезӣ шавад, ки бо гуноҳгории буб мувофиқат дошта бошад. Масалан, агар фосилаи байни ҷунбҳо дар навбати тиб 25 сантиметр бошад, бояд таъмин карда шавад, ки таъмини об кофӣ бошад, то растаниҳои сафҳои якхела афзоиш пайдо кунанд.</p><h3>Муносибати буб ва системаи обориш: назар ба растаниҳои дигар</h3><p>Принсипҳои ҳисобкунии буб барои ригон ба растаниҳои дигар монандӣ дорад. Барои фаҳмиши беҳтар муқоисавӣ, шумо метавонед миқдори буби дарахтонро санҷед, гарчанде ки миқёси он фарқ мекунад, аммо логикии идоракунии фазои афзоиш доимӣ аст. Инчунин, кашт <a href="https://navar-abyari.ir/mung-bean-seed-amount-per-hectare/">гӯштҳо ба монанди лӯбию</a> ҳам ниёз ба танзими дақиқи буб доранд, аммо ригон аз сабаби ҳассосият ба намнокии зиёд ва бемориҳои занборӣ ба тартиботи бештари ҷойгиршавии буб ниёз дорад.</p><h3>Роҳҳои амалӣ барои обории навбати тиб барои ригон</h3><ol><li><strong>Насоби рибонка:</strong> Рибонкаи тикропиро дақиқан дар миёнаи равиш ҷойгир кунед, то ки таъминот бо об мувозинат бошад. Барои раҳнамудии бештар, пеш аз насоби рибонкаи тикропи, нуқтаҳои муҳимро омад, то аз қуттани пиқкҳо пешгирӣ шавад.</li><li><strong>Конфигуратсияи пиқкҳои обдеҳандагӣ:</strong> Аз пиқкҳо бо суръати 1 то 2 литр дар соат истифода баред. Басилик намонакӣ бармаёнд, аммо обнок кардани зиёд боиси фаззидани пӯст меравад.</li><li><strong>Идоракунии фишор:</strong> Фишори система бояд байни 0.5 то 1 бар бошад. Ин фишори паст барои рибонкаи тикропӣ мувофиқ аст ва боиси нест намудани рутубати зиёд намешавад.</li></ol><p></p><h2>Нуқтаҳои амалии баланд бардоштан самаранокӣ</h2><p>Ғайр аз ҳисобу Ҳисобҳои риӕзӣ, омили мутабои зерин дар муайян кардани муваффақияти чашниди расилик нақш доранд:</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-ریحان-در-هکتار-راهنمای-جامع-جزئیات-فنی.webp" alt="مقدار بذر ریحان در هکتار: راهنمای جامع - تصویر 3"/><figcaption>normi ziraatish per hectare khoruji Rihan</figcaption></figure><ul><li><strong>Omudi zamin:</strong> Rihan barои zaminoi bo ruxsati balо va pH-i mutavassit tomon darо kor mema. Kumposti (Compost) boiyad pish az kiштi tohӣ ило кунад, то ки моддаҳои парову аз худ карда мешавад.</li><li><strong>Дархораи наҷоҳиш:</strong> Дархораи замин бояд боло аз 15 дараҷаи селсиюсӣ бошад. Кишт донаҳо дар рӯзҳои сармо савдои партоби заиракӣ ва кӯмаки бад кунат.</li><li><strong>Ҳисобсозии зарароркунандагон:</strong> Барои боди Рихан тохи хурд ҳисоб мешавад, мулоими кӯчаҳо (Mulch) метавонад зарароркунандагонро нест кунад ва тарофи замиро нигоҳ дорад. Ин кор сарфи ғизои пур ҷазб шавандани замиро кам мекунад.</li><li><strong>Қарор қарор бо маҳсулотҳои дигар:</strong> Агар фермаи шумо омехта бошад, диққат ба <a href="https://navar-abyari.ir/%d9%85%db%8c%d8%b2%d8%a7%d9%86-%d8%a8%d8%b1%d8%af%d8%a7%d8%b4%d8%aa-%db%8c%d9%88%d9%86%d8%ac%d9%87-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">ҳаҷми фурӯши оҷи дар як гектар</a> метавонад ба идоракунии давраҳои кунд ва ивазкунии рӯёнӣ кӯмак кунад. Рӯзмарра бештар ҳамчун рӯи кунд байни сатҳҳо дар баъзе системаҳои кунди омехта истифода мешавад.</li></ul><h2>Ҷавоб ба саволҳои такрорӣ (FAQ)</h2><h3>1. Беҳтарин вақти ҷоридани боди рӯзмарра куҷо аст?</h3><p>Ҷоридани боди рӯзмарра дар баҳор (аз охири апрел) ва тобистон (декабр то марти) одатан тавсия дода мешавад. Аммо, агар аз анбори кунд истифода баред, шумо метавонед кунди зимистонаро низ анҷом диҳед, вале бояд ҳароратро идора кунед, то намии боди дуруст ҷабби шавад.</p><h3>2. Оё метавонам боди рӯзмарраро бе парда (Боди холис) ҷори кунам?</h3><p>Бале, боди бо парда (Pelleted seed) кори ҷорикунии механикӣ ё дастӣ-ро осонтар мекунад, зеро бо таҷҳизоти ҷорикунанда осонтар кор карда мешавад. Боди холис лозим дорад, ки бо рег ё густош ба иловаи ҳаҷм ва парокандашавии беҳтар омехта шавад. Ин техника ба шумо кӯмак мекунад, то зичии боди-ро идора кунед ва ҷамъшавии боди-ро дар як нуқта пешгирӣ намоед.</p><h3>3. Чӣ тавр бояд системаҳои обёрӣро танзим кунам?</h3><p>Системаҳои обёрӣ набояд мустақиман бо тохм дар тамос бошанд. Фосилаи система аз ҷунҷидиш (баъди рӯи омадан) бояд тақрибан 10 то 15 сантиметр бошад. Агар система наздики тохм бошад, фишори об метавонад сурбат кардани тохмро ба вуҷуд орад. Маслиҳат дода мешавад, ки баъди нағз шудан, рӯро каме интиқол диҳед ё системаҳоро бо дақиқӣ дар самти дуруст насб кунед.</p><h2>Хулоса: Калиди муваффақият дар идоракунии тохм</h2><p>Муайян кардан <strong>Миқдори тохми тохми (бадун) дар гектар</strong> як раванди динамикии аст, ки ба мушоҳида, омӯзиш ва танзимот ниёз дорад. Оғоз бо 4 килограмм тохм дар як гектар ҳамчун хати аввалия хуб аст, вале бояд вобаста ба шартҳои замин, намуди хок ва самаранокии системаи обёрӣ қатрагӣ онро ислоҳ кунед. Бо ягонагирӣ суръати ҳадафҳо бо принсипҳои обёрӣ рӯ (тип) на танҳо хароҷоти умумӣ кам мешавад, балки сифат ва самаранокии тохми тохми (бадун) шумо ба сатҳе мерасад, ки барои бозорҳои даъоноқ ҷозиба аст. Ҳамеша тавсия дода мешавад, ки пеш аз киштҳои васеъ, як озмоишгоҳ бо суръатҳои гуногун (масалан 3, 4 ва 5 килограмм дар як гектар)-ро оғоз кунед, то беҳтарин сценариро барои шартҳои мушаххаси худ пайдо кунед. Диққат ба тафсилот дар насб кардани лӯлакашии рӯ (тип) метавонад фарқияти байни як кишт миёна ва як кишти идеалӣ бошад. Бо таҳқиқ <a href="https://navar-abyari.ir/%D9%85%D8%B2%D8%A7%DB%8C%D8%A7%DB%8C-%D9%86%D9%88%D8%A7%D8%B1-%D8%AA%DB%8C%D9%BE-%D8%A2%D8%A8%DB%8C%D8%A7%D8%B1%DB%8C-%D8%A8%D8%BA%D9%84-%D8%AF%D9%88%D8%AE%D8%AA/">Муқоисаи фоидаҳои рӯ (тип) ва қатрагӣ</a>, таъмин кунед, ки системаи интихоби шумо бо тохми тохми (бадун) шумо дар ягонагии пурра аст.</p>','Микдори бобиҳоки мятаръ дар ҳектар: Раҳнамои пурра','Ошношӣ бо принсипҳои муайян кардани миқдори бехи нана дар ҳектар дар асоси шартҳои иқлимӣ ва намуди кишт. Ин дастурон шуморо дар интихоби беҳтарин масофаи кишт ва идоракунии оборишавии қатрагӣ дастгирӣ мекунад, то ҳосилии заминаро зиёд кунед.','publish','closed','closed','miktora-bobihoki-miyatar-varekhtar',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
