INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_navar_translation_language','ar-IQ' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_navar_translation_language');
INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_title','تحلیل مقدار برداشت اسپرس في الهكتار بنظام النوار: دليل زيادة المحاصيل للفلاحين العراقيين' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_title');
INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','تعرف على كيفية تحليل وتقييم إنتاجية محصول الاسبرسو في الهكتار باستخدام نظام الري بالتنقيط (نوار تيب). دليل عملي ومختصر لمزارعي العراق لزيادة الغلات وتحسين الاستخدام الأمثل للموارد.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
