INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Мушкилоти зараррасон ва бемориҳо дар системаҳои обёрӣ андозадозӣ</h2>\n<p>Кункунии чархзан кунҳуш як усули пешрафта дар кишоварзии муосири мебошад, ки бо мақсади сабукӣ нитрогенҳои ҳавоӣ, нигоҳдории намии хок ва кам кардани маблағи парваршавӣ иҷро мешавад. Бо вуҷуди ин, тағйирёти кункунии пайдарпай ва намии доимӣ, заминаи муносиби барои пайдошавии <strong>Зараррасонҳо ва бемориҳои чархзан бо обёрӣ андозадозӣ</strong> ро фароҳам меорад. Гарчанде ки обёрӣ андозадозӣ баъд аз обёрӣ боришӣ, намӣро мустақиман дар минтақаи решаҳо ҷамъ меорад ва сатҳи хокро хушк нигоҳ медорад, ин худ метавонад мушкилоти навро ба вуҷуд орад. Хушкӣи сатҳӣ бар он оварда мерасонад, ки деҳқон эломти ибтидоии зараррасониҳои сатҳиро дертар муайян карда наметавонад, дар ҳоле ки намии баланди гуриз (тақрибан 20 то 30 сантиметрӣ) метавонад шароити идеалиро барои афзоиши занбӯруғҳои решаӣ ва вайроншавӣ фароҳам орад. Бинобар ин, дониши амиқ дар бораи таъсири озафидани усули обёрӣ, намуди пӯшишгирии чархзан ва экосистемаи хок барои идоракунии бомуваффақии ин мушкилотҳо зарур аст.</p>\n\n\n\n<h3>Таъсири обёрӣ андозадозӣ ба экосистемаи решаҳо</h3>\n<p>Системаҳои обёрӣ андозадозӣ бо сабаби эҷоди навоҳои намнок ва хушк пайдарпай, тақсимоти якхела дар хок ба вуҷуд намедиҳад. Ин хусусият ду ҷонби дорад. Аз як сӯ, хушк мондани фазои байни навоҳои намнок метавонад монеа барои пешрафти зуд баъзе курмҳои хокӣ ва зараррасониҳои хурди, ки ба намии доимӣ ниёз доранд, шавад. Аз сӯи дигар, ин навоҳои намнок, бо ғанӣ ва намӣ фарогиришуда, ҷозибаи занбӯруғҳои беморизанда монанди Fusarium ва Pythiumро зиёд мекунад. Дар кункунии чархзан, зеро ки растании ивазкунанда (одатан ғалладору монанди нӯхӯр, лӯбиё ё чигирка) мустақиман дар ин навоҳои намнок кунда мешаванд, заифиши онҳо ба бемориҳои решаӣ ду баробар меафзояд. Деҳқон бояд бидонад, ки идоракунии <strong>Зараррасонҳо ва бемориҳои чархзан бо обёрӣ андозадозӣ</strong> Лайҳаҳои хушк ба назорати дақиқтар ниёз доранд, зеро дар ин ҷойҳо беморӣ барвақт пайдо мешавад.</p>\n\n<h2>Бемориҳои қисмонии муътади дар бастаи обёркунӣ барои гольренг</h2>\n<p>Нимадаҳо ва қисмонҳои решагенҷ таърихи асосии душмани гольренг мебошанд. Дар системаҳои обёркунӣ бо тасмоққат, аз сабаби марказгаришиш рутубат дар минтақаи решаҳо, ин бемориҳо қавии бештар мегиранд. Баъзе аз бемориҳои муътади чунинанд:</p>\n<ul>\n<li><strong>Фасидшавии реша (Root Rot):</strong> Ин беморӣ дар шароите, ки партоваро ҷобадаст бо бастаи обёркунӣ рутубатӣ дорад, муътадил аст. Қисмонҳое, ба мисли Pythium ва Fusarium, дар рутубати зиёд зиёд мешаванд ва решаи ғалаи гольренгро маҳдуд мекунанд. Ишораҳои он дохили пӯлодашавӣ ва сӯфташавии сипо ва реша мебошад.</li>\n<li><strong>Сӯзондани баргҳо:</strong> Албои обёркунӣ бо тасмоққат рутубати баргҳоро кам мекунад ва ин баробарии ба бемориҳои қисмонии барг (ба мисли зангҳои сари зард)ро зиёд мекунад, аммо агар шиддати бастаи обёркунӣ хеле баланд бошад ва буғи об аз сатҳи бастаи тар ба самти пӯстҳои ғала боло баравад, метавонад муҳити тареро ба вуҷуд орад, ки пидомент ва дигар қисмонҳои қисмонӣ дар он монанд боқӣ мемонанд ва сӯзондани баргҳои поёнтарро ба вуҷуд меоранд.</li>\n<li><strong>Шаклок (Downy Mildew):</strong> Дар рӯзҳои гулбахшанда, агар рутубати нисбӣ дар сатҳи растаниҳо боиси баланд шудани анборкҳои хок дар равиши тирро шавад, шӯҳрҳо метавонанд ҳуҷум кунанд.</li>\n</ul>\n\n<p>Барои пешгирии бемориҳо, истифодаи рӯзҳои гулбахшанда, ки ба бемориҳои маҳаллӣ дар минтақаи шумо тоқат доранд, хеле муҳим аст. Илова бар ин, дӯзани хатҳои кроппии ва пешгирии ҷуфт ҷойи гулбахшанда дар минтақаҳои мушаххас яке аз принсипҳои асосии коҳиши миқдори <strong>заҳр ва бемориҳои гулбахшанда тавассути обкорӣ бо қатракушӣ</strong> мебошад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-گلرنگ-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="آفات و بیماری‌های گلرنگ با آبیاری قطره‌ای - تصویر 1"/><figcaption>crop pests diseases drip irrigation гулбахшанда</figcaption></figure>\n\n<h2>Мудирити заҳр бо истифода аз навартип</h2>\n<p>Навартип ё Tape Drip аз имконотҳои арзонтарин барои обкории гулбахшанда мебошад. Ин система аз як филми пластикӣ бо сӯрохҳои хурд (қатракуш) иборат аст, ки бевосита дар заминаи нишонии ҷойгир мешавад. Гарчанде ки навартип аз ҷиҳати таъминкунии маблағ арзонтар аст, он ҳассосияти баландтари ба банд шудан дорад. Банд шудани навартип метавонад боиси обкориҳои ноором ва рутубати нооддӣ дар баъзе нуқтаҳо шавад; заминаи барои рушди заҳр ва ҳашаротҳо, монанди зиреҳҳои талки, ки аз хушкӣ одада мешаванд. Бинобар ин, тозакунии об, ки ба навартип ворид мешавад, яке аз талаботҳои асосии барои саломатии растании гулбахшанда аст. Агар тозакунӣ дуруст набошад, навартип пур мешавад ва деҳқон нодонида шароити насафӣ-кушод барои решаҳоро ба вуҷуд меорад, ки боиси заифшудани системаи муҳофизати растаниҳо аз зарарҳои беруна мегардад.</p>\n\n\n\n<p>Иловаз тозифи об, танзими дақиқи оқими нави Tipi низ як омил муҳим аст. Оқими пасттар, ки рутубатро камтар маҳзус мекунад, метавонад ба нисбат фишори занбоорҳоро коҳиш диҳад, вале бояд ба тавре танзим шавад, ки ниёзи оби барги калов (ки одатан дар марҳилаи рушд ҳассос аст) таъмин шавад. Дар минтақаҳое, ки хокҳои гилӣ доранд, истифодаи навҳои бо фосилаҳо (Dripline) ба ҷои тиборҳои сахт баъзан мантиқӣтар аст, зеро имкони нобиёгии беҳтари обро фароҳам меорад ва аз ҷамъшавии беш аз ҳад рутубат дар пукҳои заҳазиш пешгирӣ мекунад.</p>\n\n<h2>Роҳҳои амалӣ барои кам кардани шиддати зараррасониварон ва бемориҳо</h2>\n<ol>\n<li><strong>Назорати мунтазами навҳои тар:</strong> Бар хилофи абирӣ ба таври борон, ки дар он хок пурра тар мешавад, дар абирӣ нақтӣ, ғунҷиши рутубат (Zone) бо ёрии ғунҷиши рутубат (Zone) истифода шаванд. Агар рутубат ба андозаи баланд дилхоҳ (масалан 65-70 дарсади тавоноии максималӣ барои хокҳои оловакӣ-шишӣ) расад, хатари занбоорҳо шиддатан меафзояд. Дар ин ҳолат боришотӣ бояд муваққатан қатъ шавад, то ки хок каме сахт шавад.</li>\n<li><strong>Истифодаи филтрҳои мувофиқ:</strong> Системаҳои абирӣ нақтӣ бо дақиқати баланд ба зарраҳои шиша ва шишаи хеле майд ҳассосанд. Филтрҳои дискӣ ё мушо (Mesh)-ро дар системаи худ ҷойгир кунед, то ки гузоштани навҳои Tiper ё абитубҳо коҳиш ёбад ва абирӣ якхела боқӣ монад. Оби якхела маводати беҳтар аст.</li>\n<li><strong>Поши кардани гиёҳҳо ва нӯхӯрӣ:</strong> Нӯхӯри барги калов ба шакли баъди гиёҳҳои дигар ё истифодаи чорҳоки оҷоҳон метавонад давраи ҳаёти зараррасониварони хокииро хабаргирӣ кунад. Масалан, як давраи барги каловро бо гиёҳҳое, ки барои як занбоори муайян аз ҳадди ҳоссис кам доранд, иваз кунед. Ин масъала ба таври мустақим ба потенсиали коҳиш <strong>Запарҳу ва бемориҳои баргу сӯрохӣ бо обёрӣи қатрагӣ</strong> Кӯмак мекунад.</li>\n<li><strong>Идоракунии намии наздик дар атрофи растаниҳо:</strong> Агар барои равонасозии об аз лӯлаҳои нақли об бо диаметри мувофиқ истифода мебаред, онҳоро ба таври интиқол диҳед, то аз ҷамъшавии бафки об ва намии зиёда дар атрофи сари поёнӣ пешгирӣ карда шавад.</li>\n</ol>\n\n\n\n<h3>Интихоби таҷҳизоти дуруст барои обёрӣи баргу сӯрохӣ</h3>\n<p>Интихоби таҷҳизоти мувофиқи обёрӣи қатрагӣ на танҳо ба самаранокии об марбут аст, балки бевосита ба саломатии растаниҳо таъсир мерасонад. Як намунаи маъмул, лӯлаи нахӣ 90 аст, ки ба сабаби эластикӣ ва қобилияти интиқоли фишор, интихоби хуби барои асоси обёрӣ мебошад. Ин лӯлаҳо бояд бо стандартҳои муайян интихоб шаванд, то аз шикастан ва дампашонӣ пешгирӣ карда шавад. Дампашонии об дар давоми роҳ метавонад намии зиёда эҷод кунад ва бемориҳои растаниро бадтар кунад. Барои оёмулӣ дар бораи хусусиятҳо ва фоидаҳо <a href="https://navar-abyari.ir/%d9%84%d9%88%d9%84%d9%87-%d9%86%d8%ae%db%8c-90/">Лӯлаи нахӣ 90: Раҳнамои комил, истифодаҳо ва фоидаҳо дар обёрӣ</a>моҳирони мустақими онҳоро тавсия дода мешавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-گلرنگ-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="آفات و بیماری‌های گلرنگ با آبیاری قطره‌ای - تصویر 2"/><figcaption>Афатҳо ва бемориҳои сабзавот, озувории тақчиллаҳо, калабурк</figcaption></figure>\n<p>Инчунин, агар шумо хоҳед аз ҷисми озувории навар (рашта) барои хонаи шишагӣ истифода баред, дониш пайдо кардани ҳаҷми ҳосил ва усули коркард дар ин фазои маҳдуд хеле муҳим аст. Барои маълумот бештар бо <a href="https://navar-abyari.ir/blue-irrigation-tape-greenhouse-guide-0-100/">blue irrigation tape greenhouse guide</a> шумо метавонед ба дастгирии мо муроҷиат кунед. Ин дастгирӣ ба шумо кӯмак мекунад, ки аз пайлои пурраи навар озувории (рашта) истифода баред, бе он ки шартҳои беҳавоӣ барои решаи калабурк ба вуҷуд ояд.</p>\n\n<h2>Саволҳои маъмул дар бораи афатҳо ва бемориҳои калабурк бо озувории тақчиллаҳо</h2>\n<h3>Оё озувории тақчиллаҳо ба зиёдшавии пӯсиши реша дар калабурк сабаб мешавад?</h3>\n<p>Не, албатта, аммо агар воқеияти обро дар системаи навар озуворӣ ё тақчиллаҳо мувофиқ накунад, вобароӣ боиси он мекунад, ки баъзе қисматҳо хушк ва баъзеҳо хеле тар шаванд. Қисматҳои хеле тар (бо офтобпакии заиф) муҳити муносиби барои қалакҳои пӯсогӣ, ба мисли Fusarium ва Pythium, мебароянд. Бинобар ин, тозаи об ва танзим намудани вақти озуворӣ вобаста ба қобилияти офтобпакии, калиди асосии пешгирӣ мебошад.</p>\n\n<h3>Оё метавон аз озувории тақчиллаҳо ҳамчун усули идоракунии бемориҳои афатҳои хок (ба монанди нематод) истифода бард?</h3>\n<p>Озувории тақчиллаҳо ба маънои табобот нест, аммо бо хушк мондани сатҳи хок ва кам шудани тарии умумӣ, метавонад имконияти ҳаракати баъзе нематодҳо ва кӯрпути хокро коҳиш диҳад. Аз тарафи дигар, тарии баланди қисми реша метавонад нематодҳои паразитӣ (Parasitic Nematodes)-ро фаъол кунад. Пас, ин як муколама (Trade-off) аст, ки бо нишастани навбатӣ ва интихоби гиёҳҳои калабурки ба муқовимат омода ҳал мегардад. Барои таҳқиқ бештар дар бораи озуворӣ ва рушд дар хок маълумот пайдо кунед.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-گلرنگ-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="آفات و بیماری‌های گلرنگ با آبیاری قطره‌ای - تصویر 3"/><figcaption>Харуш ва бемориҳои гирифтани гарош, обёрӣши қатқатӣ</figcaption></figure>\n\n<h3>Маслиҳат барои киштгарҳое, ки нав гарошро дар системаи қатқатӣ оғоз кардаанд?</h3>\n<p>Дар соли аввал, ҳамеша системаҳои обёрӣро бо равонакни гарош санҷед. Ямомаз ба рибҳои тирёк ё қатқатгирона имкон диҳед, ки бе шавофияти кофӣ насб шаванд. Инчунин, бо кишт кардани чархи дигари равонакӣ ва назорати дақиқ, хатарҳоро, ки аз сабаби қаробҳо ба вуҷуд меоянд, пеш аз вайроншавии бад онҳоро идора кунед. Обёрӣши қатқатӣ имкониятҳои хубро барои кам кардани стресси гармӣ барои гарош ба вуҷуд меорад, вале бояд бо нақшаи қавии саломатии решаҳо якҷоя ба истода шавад.</p>\n\n<h2>Хулоса ва роҳҳои анҷом ба анҷом</h2>\n<p>Идоракунии <strong>Харуш ва бемориҳои гарош бо обёрӣши қатқатӣ</strong> Мушкилоти дақиқи мувозинатро талаб мекунад. Бо истифода аз системаҳои рибҳои тирёк бо сифати баланд, тозакунии мувофиқи об ва назорати ниёзони шиддати хок, метавон бисёр саботи бемориворо аз дастрасо хеле кард. Равонакҳои гарош барои стресс ҳассос ҳастанд ва муҳити сустшавии решаҳо аз сабаби обёрӣши номуайян, заминаи мувофиқ барои ҳуҷуми қароб ва нематод мебошад. Истифода аз принсипҳои кишткардани мукасаб ва интихоби хатиҳо ва қатқатгирони стандартӣ, ба киштгар имкон медиҳад, ки ҳамзамон аз самаранокии об ва ҳам аз саломатии экосистемаи хок муҳофизат кунад. Ба ёд доред, ки обёрӣши қатқатӣ на танҳо як воситаи обёрӣ, балки як воситаи идоракунӣ барои назорати хатарҳои биологӣ мебошад, ки агар дуруст истифода шавад, сифати гарошро ба таври хеле баланд мекунад.</p>\n<p><strong>Мавзӯҳои алоқаманд:</strong> <a href="https://navar-abyari.ir/%d9%85%db%8c%d8%b2%d8%a7%d9%86-%d8%a8%d8%b1%d8%af%d8%a7%d8%b4%d8%aa-%d8%a7%d8%b1%d8%b2%d9%86-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Ҳаҷми ҳосили арзандар ҳектар: Рӯшноидиҳи умумии зиёд кардани бартарӣ ва фоида</a>، <a href="https://navar-abyari.ir/%D9%81%D8%A7%D8%B5%D9%84%D9%87-%D9%86%D9%88%D8%A7%D8%B1-%D8%AA%DB%8C%D9%BE-%D8%AF%D8%B1-%DA%86%D8%BA%D9%86%D8%AF%D8%B1-%D9%82%D9%86%D8%AF-%D8%A8%D9%87%D8%AA%D8%B1%DB%8C%D9%86/">D981D8A7D8B5D984D987 D986D988D8A7D8B1 D8AADB8CD9BE D8AFD8B1 DA86D8BAD986D8AFD8B1 D982D986D8AF D8A8D987D8AAD8B1DB8CD986</a></p>','Малҳо ва бемориҳои гулранги барои ободони қаторӣ: Раҳнамои умумии идоракунии','Дар ин мақола усулҳои идоракунии зараранҷӯён ва бемориҳои мурур дар гуларанг бо истифода аз системаҳои обкории қатрагӣ ва навбати тиб пेशуда шудааст, то бо кам шудани намии сатҳӣ, муқовимат ба бемориҳо баланд шавад.','publish','closed','closed','mollo-vabemorikho-gulrangi-obodoni-qatori',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
