INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','راهنمای کامل برای محاسبه مقدار مناسب بذور سبزی‌ها در هر هکتار زمین کشاورزی. شامل توصیه‌های فنی، نرخ‌های کاشت بهینه بر اساس نوع گیاه و شرایط اقلیمی، و نکات عملی برای افزایش بازدهی مزرعه با استفاده از استانداردهای جهانی (AFP) و اصول علمی مدرن.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
