INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима: Аҳамияти донистани миқдори боби сабзавотҳо дар як гектар</h2>\n<p>Барои ҳар як деҳқон, махсусан дар соҳаи сабзавоткорӣ, яке аз муроbbатҳои асосӣ муайян кардани дақиқ аст <strong>миқдори боби сабзавотҳо дар як гектар</strong> аст. Истифодаи зиёдатии боб на танҳо сарфаи пулро бо худ меорад, балки боиси зайрофӣ дар заминҳо, рақобат байни ниҳолҳо ва паст шудани сифати маҳсули ниҳоӣ мегардад. Аз тарафи дигар, кӯр кардан бо зичии камтар аз меъёрӣ имконияти заминро сармоя мебояд ва боиси кам шудани ҳосил дар як гектар мегардад. Бо дар назар доштани паҳн шудани системаҳои обёрӣ ба монанди қатрагонӣ ва парташӣ, донистани робита байни зичии кӯр ва тарзи тақсимоти об ва ғизо аҳамияти дукарата пайдо кардааст. Ин мақола талош мекунад, ки бо пешниҳоди ҷузъиёти техникӣ ва маслиҳатҳои амалӣ, роҳнамонаи ҷамъбасти барои ҳисобкунии беҳтарин истродаи боб дар кӯр кардани сабзавотҳо фаҳмонда шавад.</p>\n\n<h2>Омилҳои асосии муайян карандаи миқдори боби сабзавотҳо дар як гектар</h2>\n<p>Миқдори боб барои ҳар як гектар замин доимӣ нест, балки функсияи чанд тағйирёбандаи муҳим мебошад. Фаҳмидани ин тағйирёбандаҳо кӯмак мекунад, ки деҳқонон қарорҳои дақиқтари қабул кунанд. Муҳимтарин ин омилҳо намуди сабзавот, андозаи кӯр ва системаи идоракунии об ва заминро дар бар мегирад.</p>\n\n<h3>Намуди сабзавот ва андозаи боб</h3>\n<p>Ҳар як сабзавот хусусиятҳои махсуси худро дорад. Масалан, боби сабзии (капустаи сабз) хеле хурд ва сабук аст, дар ҳоле ки боби ғӯлӣ ё нуҳат калонтар ва вазнинтар аст. Бинобар ин, вазни боб дар як килограмм ва шумораи дандон дар як килограмм нақши марказиро дар ҳисобкунии миқдори ниҳоӣ мебозад. Одатан ҷадвалҳои стандартӣ вуҷуд доранд, вале бояд қабул кунем, ки сифати боб (фоизи пухмонӣ ва тармоӣ) низ бевосита ба миқдори истрода таъсир мерасонад. Агар фоизи пухмони боби шумо аз меъёр (масалан, зери 85 фоиз) камтар бошад, бояд миқдори бобро зиёд кунед, то ба зичии ниҳоии лозима дарсид.</p>\n\n[h3]Фавоси партоҳӣ (Фавоси байни сатҳҳо ва байни кӯтиҳо)</h3>\n<p>Шояд муҳимтарин омили муайян кардани <strong> миқдори бӯдоди сабзибоби барои гектар</strong> ин ба муайян кардани фавоси байни сатҳҳо ва фавоси байни кӯтиҳо дар дохили сатҳ бастгир аст. Ин андозаҳо вобаста ба ҳаҷми зарурӣ барои рушди реша ва тӯҷи растения, сатҳи рӯшноӣ ва дастрасӣ ба об танзим мешавад. Юна формулаи сода барои ҳисоб кардани шумораи зарраҳои сабзибоби дар гектар вуҷуд дорад: Шумораи кӯтиҳо дар гектар = 10,000,000 / (Фавоси сатҳҳо дар см × Фавоси дар сатҳ дар см). Баъд аз ҳисоб кардани ин рақам, вобаста ба вазни ҳабб, метавон миқдори бӯдодро муайян кард.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-سبزی-در-هکتار-راهنمای-جامع-تصویر-شاخص.webp" alt="مقدار بذر سبزی در هکتار: راهنمای جامع - تصویر 1"/><figcaption>норми кунҷи сабзибоби барои гектар</figcaption></figure>\n\n\n\n<h2>Таъсири системаҳои обёрӣ ба зичии партоҳи сабзибоби</h2>\n<p>Интихоби системаи обёрӣ танҳо як қарори техникӣ нест, балки мустақиман ба усули партоҳӣ ва истифодаи бӯдод таъсир мерасонад. Дар ин баҳс мо ду усули бештар истифодашаванда дар кӯти кардани сабзибоби, яъне қатрагонӣ ва нӯрипоро мундирим.</p>\n\n<h3>Обёрӣ бо усули қатрагонӣ ва анъафаксӣ дар партоҳӣ</h3>\n<p>Системаҳои ороиш бо қаплақҳо (каплкавӣ) ба сабаби парвакунии якхелаи об ва ғизо дар минтақаи решаҳо имкони кор бо зичиҳои гуногунро фароҳам меоранд. Бо вуҷуди ин, минтақаҳои таркимонанди атрофи қаплақҳо маҳдуд аст. Агар масофаи кишти буча аз қаплақҳо зиёдтар бошад, қисме аз таърифи хок аз ороишӣ бозмонда, ба харобӣ меравад. Бинобар ин, ҳангоми ҳисоб <strong>миқдори бучаи сабзавот дар гектар</strong> дар системаи қаплақӣ бояд андозаҳои киштиро чунин танзим кунед, ки решаҳои растанӣ дар минтақаи таркимонанди қаплақҳо ҷойгир бошанд. Ин дақиқгардонӣ боиси истифодаи оҳистагии об ва моддаҳои ғизоӣ мегардад ва рӯйишро ҳамгасантар мекунад. Инчунин, имкони истифодаи микси барои баромадани зичӣ вуҷуд дорад. Дар ин системаҳо шумо метавонед бо танзими масофаи қаплақҳо зичииро балотар ё поёнтар баред, то бо фазои маҳдуди об мувофиқат кунад.</p>\n\n<h3>Норбанди типӣ ва идоракурии дақиқи таркимонӣ</h3>\n<p>Ороиши нӯри типӣ, бо эҷоди норҳои таркимонанд дар тамоми сатҳ, идоракурии дақиқтари таркимониро фароҳам меорад. Ин система, махсусан барои сабзавотҳои ҳассос нисбат ба хӯракӣ ва бемориҳои шағғолӣ, хеле мувофиқ аст. Ҳангоми кишт сабзавот дар гектар бо системаи нӯри типӣ бояд диққат дошт, ки чуқурии дохилишавии об ва эни норҳои таркимонанд муайянкунандаи масофаи бехатари байни сатҳҳо мебошад. Кишти хеле зич дар системаи нӯри типӣ метавонад боиси зиёд шудани таркимонии нисбӣ ва паҳншавии бемориҳои фунгусӣ дар таҷи растанӣ гардад. Бинобар ин, метавонад зарурат бошад, ки зичиро каме кам кунед, то ҳавои дурахши таҷи растания ҳифз шавад. Ин мувозинат калиди дастоварди маҳсулоти сифатнок дар системаҳои нӯри типӣ аст. Дар ин ҷо, барои фаҳмиши беҳтари фарқиятҳо, шумо мавзӯҳои мунтабириро дар бораи сарфаҳои нӯри типӣ ҷустуҷӯ метавонед.</p>\n\n\n\n<h2>Роҳнамои ҳисобкуниҳо ва қоидаҳои амалӣ</h2>\n<p>Барои дар назорд доштани ҳамаи омилҳо, марҳилаҳои зерини амалиро пайравӣ кунед:</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-سبزی-در-هکتار-راهنمای-جامع-کاربرد-عملی.webp" alt="مقدار بذر سبزی در هکتار: راهنمای جامع - تصویر 2"/><figcaption>seed rate per hectare crop сабзавот</figcaption></figure>\n<ol>\n<li><strong>Таҳлили хок ва муайянкунии мушкилот:</strong> Агар хок аз шумургии баланд ё зарбурдандагии паст нафоси шабист шояд, зиёди коркардани ғунтро кам кунед, то таъсири бад ба наботот кам шавад. Таҳлили дақиқи хок пеш аз катон оморҳои муҳимро барои танзими фосилаи нишон медиҳад.</li>\n<li><strong>Интихоби андозаҳои катон аз рӯи системаи овар:</strong> Андозаҳои катонро (фосилаи сафҳо ва фаръӣ) бингаред, то ки дар омехташавӣ бо системаи овар (бо қутраҳо ё бастӣ бастӣ) беҳтарин шавад. Дар системаи бо қутраҳо, фосилаи решаҳо бояд бо фазои хоби қутрагирҳо мувофиқат кунад.</li>\n<li><strong>Ҳисоб кардани шумораи наботот ва вазни бадҳо:</strong> Аз рӯи андозаҳои интихобшуда, шумораи набототро дар гектар ҳисоб кунед. Сипас, бо назардошти сатҳи ҷаврашавӣ ва вазни дун, миқдори бадро муайян кунед. Бояд дар хотон доред, ки ҳамеша ҳадди имконпазир (аз 10 то 15 фоиз) барои ислоҳи имконпазири мушкилотро ба назар гиред.</li>\n<li><strong>Ҳомусозии тарқу ва мувозинати об ва ғизо:</strong> Дар системаи бастӣ бастӣ, дақиқӣ дар чуқурӣ ва пуршии бастии хоби, мустақиман ба овишди ҳамоҳанги решаҳо ва натиҷоан ба истеъмоли бадҳои аввал таъсир мерасонад. Агар тарқуи бастӣ ноомонманд бошад, намоиши ноомонманди наботот ба рақобати дохилӣ ва кам шудани ҳосил меояд.</li>\n</ol>\n\n<h2>Муқоисаи zichӣ дар сабзиёти истифодашаванда</h2>\n<p>Дар ҷадвали зер қимматҳои тахминӣ <strong>Микдори тоҳир сабзӣ дар ҳектар</strong> барои баъзе сабзиёти оддӣ бо дар назар гирифтани zichӣҳои меъёрӣ (ба ҳисоббардорӣ партобун аз сатҳи зист ва шароитҳои иқлими муносиб) оварда шудааст. Ин микдорҳо танҳо роҳнамоанд ва бояд бар асоси андозаҳои дақиқи партобии шумо ислоҳ карда шаванд:</p>\n<table border="1" cellpadding="5" cellspacing="0" style="border-collapse: collapse; width: 100%;">\n<thead>\n<tr>\n<th>Навъи сабзӣ</th>\n<th>Фосилаи байни қаторҳо (сантиметр)</th>\n<th>Фосилаи байни наботот (сантиметр)</th>\n<th>Шумораи наботот дар ҳектар (тахминӣ)</th>\n<th>Мiqdори бaзрӣ, ки дар ҳекта зарур аст (килограм - тахминӣ)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Ғолабӣ</td>\n<td>40-50</td>\n<td>30-40</td>\n<td>53,850 - 66,666</td>\n<td>4 - 5</td>\n</tr>\n<tr>\n<td>Помидор</td>\n<td>70-80</td>\n<td>40-50</td>\n<td>25,000 - 35,714</td>\n<td>4 - 5</td>\n</tr>\n<tr>\n<td>Бодомҷан</td>\n<td>70-80</td>\n<td>45-50</td>\n<td>25,000 - 28,571</td>\n<td>10 - 12</td>\n</tr>\n<tr>\n<td>болтороқ</td>\n<td>60-70</td>\n<td>40-45</td>\n<td>31,746 - 46,301</td>\n<td>5 - 7</td>\n</tr>\n<tr>\n<td>шало / пиёз</td>\n<td>30-35</td>\n<td>8-10</td>\n<td>285,714 - 416,666</td>\n<td>100 - 150</td>\n</tr>\n</tbody>\n</table>\n<p>Ҳамон тавре ки мебинед, байни сабзавотҳо фарқияти зиёд мавҷуд аст. Барои маълумоти бештар дар бораи ҳаҷми хориҷи дигар маҳсулот, ки метавонанд дар деҳот ё заминаҳои омехта ҷушконда шаванд, метавонед ба <a href="https://navar-abyari.ir/%d9%85%db%8c%d8%b2%d8%a7%d9%86-%d8%a8%d8%b1%d8%af%d8%a7%d8%b4%d8%aa-%d8%b3%db%8c%d8%b1-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Ҳаҷми хориҷи сирпои дар як гектар</a> ва <a href="https://navar-abyari.ir/garlic-seed-per-hectare-factors-increase/">омилҳои таъсирунокӣ ба зиёд шудани тоблҳои сирпо дар як гектар</a> таваҷҷӯҳ кунед. инчунин, шинохти муқоисавӣ бо дигар маҳсулот, масалан ҳаҷми хориҷи кӯбобҳои сабз дар як гектар, метавонад дидангезии васеҳтарро ба вуҷуд орад.</p>\n\n\n\n<h2>Саволҳои маъмулӣ (FAQ)</h2>\n<h3>Оё оварии бандонавӣ метавонад миқдори талабшавии боронро кам созад?</h3>\n<p>Ба таври мустақим не, аммо бо баланд бардоштани самаранокии истифодаи об ва кам кардани стресси решагӣ, метавонад ба шумо имкон доҳад, ки бо зичии кишт, ки аз ҷиҳати манбаъҳои моеъ ва рӯшноӣ мувофиқ аст, ба афзоиши беҳтар ноил шавед. Агар решаҳо аз сабаби камбудии об ба андозаи пурра расонаданд, растаи заиф мешавад ва метавонад шуда, шумо маҷбур бошед ки кишти пинҳонӣ анҷом диҳед. Бинобар ин, системаи дақиқи оварии бандонавӣ ба шумо иҷозат медиҳад, ки аз максимали ҳайати чигили дилхоҳи худ истифода баред, бе он ки аз отроҳи растаҳо аз сабаби стресси хушкӣ огоҳ бошед.</p>\n\n<h3>Дар системаи чангчандӣ, агар масофаи кишт аз чангчандҳо дур бошад, чӣ ҳодиса меафтад?</h3>\n<p>Дар ин ҳолат, решаҳои раста барои дастрасӣ ба об бояд масофаи бешаро тай кунанд ва энергияи бештар сарф кунанд. Инчунин, моддаҳои ғизоии, ки аз роҳи чангчандҳо пешниҳод мешаванд, метавонанд ба решаи асосӣ нарасанд. Ин метавонад ба кам шудани афзоиши раста ва кам шудани самаранокии истифодаи борон оварда расонад. Бинобар ин, дар системаи чангчандӣ, мувофиқати масофаи кишт бо устувории банди намнок муҳим аст.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-سبزی-در-هکتار-راهنمای-جامع-جزئیات-فنی.webp" alt="مقدار بذر سبزی در هکتار: راهنمای جامع - تصویر 3"/><figcaption>миқдори борон бар гектар баҳои сабзӣ</figcaption></figure>\n\n<h3>Оё миқдори борон дар хокҳои сабук ва вазнин фарқияте дорад?</h3>\n<p>Бале, фарқиятҳои хурд вуҷуд дорад. Дар хокҳои сабук, ки зарфшавии беҳтар доранд, метавонад масофаҳои каме фарқ карда бошанд, аммо фарқияти асосӣ дар дараҷаи ниёз ба об аст. Дар хокҳои вазнин, ки боридан душвортар аст, баъзан бо кам кардани зичии кишт ва зиёд кардани масофаи байни растаҳо, метавон стресси растаиеро кам кард. Дар шартҳои чунин, миқдори умумии борон дар гектар ба таври замонӣ кам мешавад.</p>\n\n<h2>Хулоса</h2>\n<p>Муайяни дақиқ <strong>Молдои тухмии сабзавот дар ҳектар</strong> Ин раванди мураккаб аст, ки дарки амиқ аз намуди сабзавот, шароити замин ва намуди системаи ороии истифодашударо дар бар мегирад. Системаҳои орои навбатмонанди қапчаноӣ ва нави чӯпӣ, бо фароҳам овардани устувории мунтазами намнокӣ, имконияти бузургро барои зиёд кардани самаранокӣ ва сифати маҳсулот доранд. Бо мувофиқат кардани андозаҳои гирифтан бо ин системаҳо, метавон аз истифодаи оптималии моддаҳо, афруишди ҳомили парҳези занбӯрҳо ва дар натиҷа зиёд кардани даромади заминдориро таъмин кард. Маслиҳат дода мешавад, ки пеш аз ниҳолӣ, аз иттилоотҳои маҳаллӣ ва таҷрибаи худ истифода баред ва ҳисоботҳоятонро бо ҳудуди имконпазирӣи кофӣ анҷом диҳед.</p>\n<p><strong>Мавзӯи алоқаманд:</strong> <a href="https://navar-abyari.ir/%D8%B1%D8%A7%D9%87%D9%86%D9%85%D8%A7%DB%8C-%D8%AC%D8%A7%D9%85%D8%B9-%DA%A9%D8%A7%D8%B4%D8%AA-%D8%AE%DB%8C%D8%A7%D8%B1-%D8%A8%D8%A7-%D8%B1%D9%88%D8%B4-%D8%A2%D8%A8%DB%8C%D8%A7%D8%B1%DB%8C/">D8B1D8A7D987D986D985D8A7DB8C D8ACD8A7D985D8B9 DAA9D8A7D8B4D8AA D8AEDB8CD8A7D8B1 D8A8D8A7 D8B1D988D8B4 D8A2D8A8DB8CD8A7D8B1DB8C</a>， <a href="https://navar-abyari.ir/garlic-seed-per-hectare-factors-increase-37460-2/">garlic seed per hectare factors increase 37460 2</a></p>','Мавқии бодаи сабзавот дар һектар: Ҷиҳати пурраи ҳатмӣ','Оё медонед, ки барои ҳар гектар замин ба дақиқ чӣ андоза тоҳии сабзаҳо лозим аст? Дар ин раҳнамоии ҷамъбасти шумо ҳисоб кардани зичии бехронӣ, интихоби тоҳии мувофиқ бар асоси системаи обёркунӣ бо тарвиши қатрагӣ ва стрип-тип ва омилҳое, ки ба истеъмолоти тоҳӣ таъсирас мекунанд, мебаррасем.','publish','closed','closed','movii-bodi-sabzavot-hoktar-rahnomo',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
