INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>مقدمة: أهمية تحديد الكثافة الصحيحة لزراعة الدخن</h2>\n<p>إن زراعة الدخن تعد ركنًا أساسيًا من أركان تغذية الماشية في المناطق شبة الجافة والجافة. تحديد <strong>كمية بذور الدخن لكل هكتار</strong> ليست عملية بسيطة تُنفذ استنادًا إلى التخمين؛ بل تتطلب فهمًا عميقًا للفسيولوجيا النباتية، وحالة التربة، وإدارة موارد المياه. في الظروف الشائعة التي يستخدم فيها المزارعون أنظمة الري الحديثة بنظام الليزر، يوجد ارتباط مباشر بين المسافات بين صفوف الزراعة والتسقي (Spacing). إذا كانت كثافة البذور مفرطة، فإن التنافس الداخلي بين النباتات على امتصاص الماء والعناصر الغذائية يؤدي إلى انخفاض وزن كل شجيرة، وبالتالي انخفاض إجمالي المحاصيل. من ناحية أخرى، فإن الكثافة المنخفضة عن الحد المثالي تقيّد إمكانية تغطية المساحة والإنتاجية. في هذا الدليل، هدفنا هو تقديم إطار علمي تطبيقي حتى تكون قرارات الزراعة الخاصة بك أكثر دقة واقتصاديًا ومتوافقة مع طرق الري الحديثة.</p>\n\n<p>يحتل الدخن مكانة خاصة بسبب تنوع أصنافه (علفية وحبيبية) وتكامله مع ظروف الإجهاد المائي. لكن للاستفادة من هذه المزايا، يجب أن تعرف أن إدارة الكثافة النهائية تُعدّ هندسة تُعدّل بالتزامن مع جدول الري. يشكو العديد من المزارعين من أن العلف الذي يحصدونه ينخفض من حيث الكثافة والجودة؛ والسبب الرئيسي غالبًا هو عدم تطابق كمية البذور الأولية مع مسافات مواسير الري.</p>\n\n\n\n<h2>العوامل المؤثرة في تحديد كمية بذور الدخن لكل هكتار</h2>\n<p>لا يوجد رقم ثابت للتغطية في كل منطقة، لأن عدة عوامل تدخل في هذا الحساب. أهم هذه العوامل هو هدف الزراعة (علف أم حبوب) ونظام الري. في زراعة العلف، الهدف هو الكتلة الخضراء، لذا يمكن أن تكون الكثافة أعلى قليلاً للحصول على تغطية أسرع. لكن في زراعة الحبوب، يجب الاهتمام بالمساحة الكافية لتكوين العناقيد الحاملة للثمار واستواء الحب كاملة. وهذا يعني أن المسافات بين الصفوف والنباتات تتغير، وبالتالي يتغير مقدار البذور المطلوبة للفدان.</p>\n\n<h3>دور نظام الري بالخطوط في زراعة الذرة</h3>\n<p>في الري بالتنقيط والخطوط، يُستخدم الماء مباشرة عند الجذور. إذا زُرعت بذور الذرة قريبة جداً من خط الزراعة، ستتشابك جذور النباتات معاً وقد يضغط ذلك على نظام الري ويعطل حركة الماء. أيضاً، الكثافة العالية للنباتات بالقرب من الخط ستجبر النباتات في مرحلة النمو السريع على تحمل الإجهاد بسبب المنافسة الشديدة. ومن جانب آخر، المسافات القياسية لزراعة علف الذرة في نظام الري بالخطوط، كما هو موضح في الدليل <a href="https://navar-abyari.ir/corn-drip-tape-spacing-forage-corn-guide/">مسافات زراعة علف الذرة بنظام الري بالخطوط</a> تقديم، يمكن أن تكون نموذجاً مشابهاً لإدارة الذرة، لأنهما مجاورتان من حيث احتياجات الجذور. التأكد من أن البذore زُرعت في العمق والمسافة المناسبة من الأنبوب هو مفتاح النجاح.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-سورگوم-در-هکتار-راهنمای-جامع-تصویر-شاخص.webp" alt="مقدار بذر سورگوم در هکتار: راهنمای جامع - تصویر 1"/><figcaption>seed rate per hectare crop سورگوم</figcaption></figure>\n\n<h3>المناخ وسعة احتباس الماء في التربة</h3>\n<p>في المناطق ذات هطول الأمطار المنخفض وسعة احتباس الماء المنخفضة، تؤدي الزراعة كثيفة إلى نقص الماء للجذور. لذا، في هذه المناطق، يمكن تقليل كمية البذور وزيادة المسافات (مثلاً من 10 كغ إلى 7 كغ للفدان مع زيادة مسافة الصفوف) لتحسين الجودة والوزن الجاف للنبات. بالمقابل، في الحدائق ذات الماء الوفير أو الري الجوفي المناسب، يمكن رفع الكثافة قليلاً لتحقيق أقصى تغطية.</p>\n\n\n\n<h2>جدول إرشادي لمدى بذرة الذرة الرفيعة حسب هدف الزراعة</h2>\n<p>في ما يلي، تجدر الإشارة إلى أن هذه الأرقام هي مقاييس مقترحة بناءً على الأصناف التجارية الشائعة، ويجب أن يتم تكييفها بالمشورة مع مركز خدمات الزراعة الإقليمي. الفرق الرئيسي في كثافة النباتات النهائية في المتر.</p>\n\n<table>\n  <thead>\n    <tr>\n      <th>هدف الزراعة</th>\n      <th>المسافة بين الصفوف</th>\n      <th>المسافة بين النبتة والنبتة</th>\n      <th>الكمية التقديرية للبذور (كغ/هكتار)</th>\n      <th>عدد النباتات النهائي/هكتار</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <td>علفية (حصاد متعددة المراحل)</td>\n      <td>٩٠ سم</td>\n      <td>١٥-٢٠ سم</td>\n      <td>١٠ إلى ١٥</td>\n      <td>٥٠٬٠٠٠ إلى ٧٠٬٠٠٠</td>\n    </tr>\n    <tr>\n      <td>حبوب (إنتاجية عالية)</td>\n      <td>٩٠-١٠٠ سم</td>\n      <td>٢٠-٢٥ سم</td>\n      <td>٧ إلى ١٠</td>\n      <td>۴۰,۰۰۰ الی ۵۵,۰۰۰</td>\n    </tr>\n    <tr>\n      <td>علفي (قطفة واحدة)</td>\n      <td>۱۰۰ سنتيمتر</td>\n      <td>۲۵-۳۰ سنتيمتر</td>\n      <td>۵ الی ۸</td>\n      <td>۳۳,۳۳۳ الی ۴۰,۰۰۰</td>\n    </tr>\n  </tbody>\n</table>\n\n<p>ملاحظة مهمة: إذا كنتم تستخدمون الخيط اليدوي، فإن الدقة في الحفاظ على مسافة ثابتة أمر بالغ الأهمية. قد يؤدي عدم الانتظام في الزراعة إلى تنافس جذري غير متماثل، مما يجعل إدارة المياه صعبة في الري بنظام التنقيط.</p>\n\n<h2>نقاط عملية لتحسين الزراعة بنظام التنقيط</h2>\n<p>كما ورد في دليل <a href="https://navar-abyari.ir/comprehensive-irrigation-tape-greenhouse-guide-0-to-100/">ري الحقول المحمية بنظام الري بالتنقيط</a> فكما هو موضح، يضاعف التوافق بين الموعد المناسب للزراعة ونظام الري من فرص النجاح بعدة أضعاف. وفي الحقول المفتوحة، تزداد حساسية هذه المسألة ضعفَ ما هي عليه. فيما يلي بعض الإرشادات العملية التي يجب مراعاتها:</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-سورگوم-در-هکتار-راهنمای-جامع-کاربرد-عملی.webp" alt="مقدار بذر سورگوم در هکتار: راهنمای جامع - تصویر 2"/><figcaption>معدل البذر للเฮكتار محاصيل سورغوم</figcaption></figure>\n<ul>\n  <li><strong>عمق زرع البذور:</strong> يعد سورغوم حساسًا فيما يتعلق بالبذرة. يجب ألا يتجاوز عمق زرع البذور من 3 إلى 5 سم. في التربة التي تُركَّب فيها خط الري بالتنقيط بعمق 3-4 سم، يجب زراعة البذرة بالضبط على مسار خط الماء لضمان إنبات متجانس.</li>\n  <li><strong>التحكم في الكثافة النهائية:</strong> بعد الإنبات، قم بحساب عدد النباتات في كل متر طولي من الصف. إذا كانت الكثافة أكبر من الحد المطلوب، فكّر في إجراء التقليم اليدوي أو الفلح المحلي. يشبه هذا الإجراء مبادئ التقليم لزيادة جودة وكمية الذرة العلفية، إذ يخلّص النباتات الرئيسية من منافسيها.</li>\n  <li><strong>إدارة الرطوبة أثناء الزراعة:</strong> إذا كانت التربة جافة، يُنصح بالري الغزير قبل الزراعة أو في نفس الوقت للحفاظ على الرطوبة اللازمة للإنبات. يتم الري بالتنقير (الخطي) في هذه المرحلة بالضغط المنخفض والحجم العالي.</li>\n</ul>\n\n<p>كما أن الاهتمام بالنقاط قبل شراء أنبوب الري بالتنقير (الخطي) لضمان جودة التنظيف وعدم انسداد الفتحات الدقيقة في التربة الطينية أمر ضروري، حيث أن الانسداد في الأنبوب قد يؤدي إلى موت النباتات في تلك المنطقة وجعل تكلفة الزراعة غير فعالة.</p>\n\n<h2>الأسئلة الشائعة</h2>\n<h3>هل يؤثر اختلاف الأصناف الأعلافية والحبوبية من القمح (السورجوم) على كمية البذور؟</h3>\n<p>نعم. الأصناف الحبوبية عادةً ما يكون حجم بذورها أكبر، وتكون كثافة عدد البذور في الكيلوغرام أقل مقارنةً بأصناف الأعلاف ذات البذور الصغيرة. لذلك، يختلف وزن البذور المطلوب لتحقيق الكثافة النباتية نفسها. تحقق دائمًا من كثافة البذور (DWT) الموجودة على العبوة.</p>\n\n<h3>ما هو أفضل وقت لزراعة السورجوم للاستفادة من الري بالتنقيط؟</h3>\n<p>في المناطق الشمالية، من منتصف إلى أواخر أبريل (فروردین)؛ وفي المناطق الجنوبية، من ديسمبر (آذر) حتى الخريف. يجب أن يكون توقيت الزراعة بحيث تكون الموارد المائية والضوئية كافية للنبات خلال مراحل النمو الحساسة (من 30 إلى 45 يومًا بعد الزراعة) لتجنب الإجهاد الحراري في المراحل المبكرة من النمو.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-سورگوم-در-هکتار-راهنمای-جامع-جزئیات-فنی.webp" alt="مقدار بذر سورگوم در هکتار: راهنمای جامع - تصویر 3"/><figcaption>معدل بذرعلاصالح سورغوم</figcaption></figure>\n\n<h3>هل يمكن استخدام معدل بذروعلاصالح لزراعة سورغوم؟</h3>\n<p>لا، وعلى الرغم من تشابهيهما، إلا أن حجم الحبة وقدرتها على الإنبات تختلف. بذروعلاصالح أصغر حجمًا عادةً ولها توزيع أكثر نعومة. استخدام معدلات بذروعلاصالح يمكن أن يؤدي إلى بذروعلاصالح الزائدة (Overseeding) وفشل المحصول. المصادر المشابهة مثل <a href="https://navar-abyari.ir/melon-seed-quantity-per-hectare-planting-density-table/">معدل بذروعلاصالح للبطيخ للعقل</a> يؤكد أيضًا على ضرورة حساب أي زراعة استنادًا إلى تحليل بذروعلاصالح الخاص بها.</p>\n\n<h2>الخلاصة</h2>\n<p>تحديد دقيق <strong>معدل بذروعلاصالح سورغوم للعقل</strong> هناك طريقة ديناميكية تعتمد على هدف الزرع (علف أو بذرة) ونوع التربة والمناخ ونظام الري. استخدام نظام الشريط المتقطع يزيد من العائد، ولكن فقط إذا كان كثافة النباتات متسقة مع سعة الجذور ومتطلبات الماء. أي خطأ في كثافة الزراعة يعرض استثمارك للخطر. التوصية النهائية هي أن تبدأ بتسجيل بياناتك من السنة الأولى: عدد النباتات في المتر، المسافة بين النباتات، ونسبة الإنبات. ستساعدك هذه البيانات في السنة التالية على تقدير كمية البذور المطلوبة بدقة أكبر. الزراعة الدقيقة هي ما يجعل المستقبل أكثر إشراقًا ويضمن الكفاءة الاقتصادية.</p>\n<p><strong>مقالات ذات صلة:</strong> <a href="https://navar-abyari.ir/%d9%85%db%8c%d8%b2%d8%a7%d9%86-%d8%a8%d8%b1%d8%af%d8%a7%d8%b4%d8%aa-%d8%b0%d8%b1%d8%aa-%d8%b9%d9%84%d9%88%d9%81%d9%87%d8%a7%db%8c-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">حصاد الذرة العلفية للهكتار: دليل شامل لزيادة العائد والأرباح</a></p>','كمية بذور الدكر في الهكتار: دليل شامل','الاختيار الصحيح لجرعة بذور الدخن لكل هكتار يتطلب مراعاة العوامل المناخية ونوع الزراعة ونظام الري. يقدّم هذا المقال، مع التركيز على الري بالتنقيط والري النطاقي، دليلاً كاملاً لتحديد كثافة الزراعة وزيادة العائد الاقتصادي. من خلال مراجعة جداول المسافات والنقاط العملية، ستدرك كيف يمكنك منع هدر الموارد والوصول إلى أقصى إنتاج للأعلاف أو الحبوب. صُمّمت هذه التعليمات للفلاحين المحترفين الذين يسعون إلى رفع مستوى إنتاجهم الزراعي.','publish','closed','closed','sorghum-seed-quantity-hectar-guide',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
