INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима: Аҳамияти муайян намудани зичии нақшҳои ғарамсум (сорго)</h2>\n<p>Карбунии ғарамсум (сорго) яке аз унсурҳои асосии ғизои чорво дар минтаҳои нимхушк ва хушк мебошад. Муайян кардани <strong>миқдори тоҷи ғарамсум (сорго) дар ҳектар</strong> як раванди сода нест, ки танҳо бо тахмин ва андеша иҷро шавад, балки дарк амиқ аз физиологияи растаниҳо, ҳолати хок ва идоракунии манбаъҳои обро талаб мекунад. Дар шароити умумие, ки деҳқонон аз системаҳои ороғи муосири навъи «тип» (drip) истифода мебаранд, робитаи бевосита байни фосилаҳои нақшгузорӣ ва ороғ (Spacing) вуҷуд дорад. Агар зичии тоҷи беш аз ҳад бошад, рақобати дохилӣи растаниҳо барои ҷазби об ва моддаҳои ғизоӣ боиси кам шудани вазни ҳар як нома (бутта) ва дар натиҷа, кам шудани ҳаҷми умумии маҳсулот мегардад. Аз тарафи дигар, зичии камтар аз ҳадди лозима, имконияти фаро гирифтани замин ва истеҳсолиро маҳдуд мекунад. Дар ин дастурамал мақсади мо пешниҳуди як чорчубаи илмию амалии буда, то қарорҳои нақшгузории шуморо дақиқтар, иқтисодӣтар ва мувофиқ ба усулҳои муосири ороғ созмон диҳад.</p>\n\n<p>Ғарамсум (сорго) бо сабаби гуногунии шаклҳои он (печина ва тоҷидор) ва мутобиқшавӣ бо шароити стресси обӣ, ҷойгоҳи махсус дорад. Аммо барои фоидаовардани аз ин бартарӣҳо, бояд донед, ки идоракунии зичии ниҳоӣ як инжинерист, ки ҳамзамон бо нақшаи ороғ танзим мешавад. Бисёр деҳқонҳо шикоят мекунанд, ки печинаеро, ки мебаранд, аз нигоҳи зичӣ ва сифат дар ҳолати паст шудан аст; сабаби асосии аксар вақт ноамолии миқдори аввали тоҷ бо фосилаҳои насби лӯлаҳо мебошад.</p>\n\n\n\n<h2>Омилҳои таъсиррасон ба муайян кардани миқдори тоҷи ғарамсум (сорго) дар ҳектар</h2>\n<p>Намоиши як адади муайян барои ҳар минтақа ғайриимкон аст, зеро омили бисёр дар ҳисобкунии он нақш доранд. Муҳимтарин ин омилҳо мақсади партов (ӯтӣ ё дон) ва намуди системаи оборӣ мебошанд. Дар партови оҳамӣ мақсад ҳаҷми сабзӣ аст, бинобар он зичӣ метавонад каме баландтар бошад, то пӯшиши тезтар ба вуҷуд ояд. Аммо дар партови дунӣ бояд ба ҷойи кофӣ барои ташкили бухори дундор ва пухтани пурраи дон эътибор дод. Ин масъала боиси тағйир додани масофаи сутунто-сутунто ва ноҳо-ноҳото мешавад ва дар натиҷа, миқдори ниёзманди дон дар ҳектар фарқ мекунад.</p>\n\n<h3>Нақши системаи обории нибони рибонавӣ дар гузоштан</h3>\n<p>Дар обории қатқатӣ ва нибони рибонавӣ об дақиқан дар решаҳо истифода мешавад. Агар дони соргометроҳро хеле наздик ба рибонаи партов гузоред, решаҳои растаниҳо хӯрда мешаванд ва метавонанд ба фишори системаи оборӣ ва оҳистакунӣ дар ҳаракати об оварда расонанд. Инчунин, зичии баланди растаниҳо дар наздикии рибона боиси он мешавад, ки растаниҳо дар марҳилаи тезии рушд, бо сабаби рақобати шадид, фишорҳоро ба инобат оранд. Аз тарафи дигар, масофаҳои стандартии партори зори оҳамӣ дар обории нибони рибонавӣ, ки дар раҳономии <a href="https://navar-abyari.ir/corn-drip-tape-spacing-forage-corn-guide/">Масофаи партори зори оҳамӣ бо нибони рибонавӣ</a> баён шудааст, намунае мушобиҳро барои идоракунии соргометроҳ низ мебошад, зеро аз ҷиҳати зарурати решагӣ ҳамсояҳоянд. Таъйид кардани он, ки дон дақиқан дар чуқурӣ ва масофаи мувофиқ аз лӯла партофта шавад, калиди муваффақият аст.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-سورگوم-در-هکتار-راهنمای-جامع-تصویر-شاخص.webp" alt="مقدار بذر سورگوم در هکتار: راهنمای جامع - تصویر 1"/><figcaption>miqdori don dar hektar zir\'ati sorogum</figcaption></figure>\n\n<h3>Иқлим ва ҳуҷрабардории оби хок</h3>\n<p>Дар минтақаҳое, ки томоншавӣ кам аст ва ҳуҷрабардории оби хок паст аст, партори зич оварда расонидан ба камбудии оби решагӣ оварда мерасонад. Бинобар ин, дар ин минтақаҳо, кам кардани миқдори дон ва зиёд кардани масофаҳо (масалан, аз 10 килограмм то 7 килограмм дар ҳектар бо зиёд шудани масофаи сутунто) метавонад ба баланд шудани сифат ва вазни хушкшудаи растани оварда расонад. Баръакс, боғҳо дар обҳои зиёд ё дар зеробии мувофиқ, метавонанд зичиро каме боло баранд, то пӯшиши ҳадди аксарро дошта бошанд.</p>\n\n\n\n<h2>Ҷадвали пешниҳоди миқдори тухми сорго вобаста ба ҳадафи кбуд</h2>\n<p>Дар поён диққат кардан лозим аст, ки ин рақамҳо миқдорҳои пешниҳодшуда бар пояи шаклҳои таркомӣ-баҷо мебошанд ва бояд бо маслиҳати маркази хизматрасониҳои кӯҳии минтақавӣ мутобиқ карда шаванд. Фарқ асосӣ дар зичии ниҳоии ниҳолҳо дар المتر аст.</p>\n\n<table>\n  <thead>\n    <tr>\n      <th>Ҳадафи кбуд</th>\n      <th>Фосилаи қаторҳо</th>\n      <th>Фосилаи байни ниҳолҳо</th>\n      <th>Миқдори тахминии тухм (кг/ҳектар)</th>\n      <th>Шумораи ниҳоии ниҳол/ҳектар</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <td>Камчӯби (гирифтани якчанд марҳила)</td>\n      <td>90 см</td>\n      <td>15–20 см</td>\n      <td>10 то 15</td>\n      <td>50,000 то 70,000</td>\n    </tr>\n    <tr>\n      <td>Дона (барорандамии баланд)</td>\n      <td>90–100 см</td>\n      <td>20–25 см</td>\n      <td>7 то 10</td>\n      <td>40,000 то 55,000</td>\n    </tr>\n    <tr>\n      <td>Осорӣ (даракаи якмавҷаҳо)</td>\n      <td>100 сантиметр</td>\n      <td>25-30 сантиметр</td>\n      <td>5 то 8</td>\n      <td>33,333 то 40,000</td>\n    </tr>\n  </tbody>\n</table>\n\n<p>Нуқтаи муҳим: Агар аз планиерҳои дастӣ истифода бардаед, дақиқӣ дар нигоҳ доштани фосилаи устувор хеле муҳим аст. Ноустувории нишоҳӣ метавонад ба рақобати ноамрисҳои решаҳо оварда расонад, ки дар обёрӣ бо шитобҳо идоракунӣро душвор мекунад.</p>\n\n<h2>Нуқтаҳои амалӣ барои беҳтарсозии нишон бо шитобҳо</h2>\n<p>Чун дар роҳнамои <a href="https://navar-abyari.ir/comprehensive-irrigation-tape-greenhouse-guide-0-to-100/">обории хонаҳои шабат бо нап</a> аз рӯи зикр шудааст, мувофиқсозии вақти бокорӣ ва системаи обори ба ҳосилии меъёрро чанд баробар меафзояд. Дар заминҳои кушод, ин масъала ду баробар ҳассост. Чанд нуқтаи амалии, ки бояд риоя кард:</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-سورگوم-در-هکتار-راهنمای-جامع-کاربرد-عملی.webp" alt="مقدار بذر سورگوم در هکتار: راهنمای جامع - تصویر 2"/><figcaption>шумораи бодӣ дар ҳектар барои парҳези сорго</figcaption></figure>\n<ul>\n  <li><strong>Даввати бокори бодӣ:</strong> Сорго ба боди майда ҳассост. Даввати бокорӣ наметавонад беш аз 3 то 5 сантиметр бошад. Дар хок, ки нап дар давати 3-4 см ҷойгир аст, бодро бояд дақиқан дар хат оби баробар бидарӣ, то нӯг дохил равад.</li>\n  <li><strong>Назорати зичии натиҷавӣ:</strong> Пас аз нӯг дохил шудан, шумораи растаниҳоро дар ҳар метри дарозиї хати ҳисоб кунед. Агар зичӣ аз меъёри илтимоси зиёд бошад, қатъ кардани дасти ё куштани хакро дар назар гиред. Ин раванд, монанди принсипҳои қатъ кардан барои зиёд кардани сифат ва миқдори сабзавот дар сӯйи хӯрок аст, зеро растаниҳои асосиро аз рақибон озод мекунад.</li>\n  <li><strong>Мудории намҳои ҳангоми боридан:</strong> Агар хок хушк бошад, барои нигоҳ доштани намӣ барои нӯмӯзиш, оборӣи вазнин пеш аз боридан ё дар вақти боридан тавсия мегардад. Дар ин марҳала оборӣи навори дрип бо фишори паст ва ҳаҷми баланд иҷро мешавад.</li>\n</ul>\n\n<p>Инчунин, барои таъмини сифати муносиби шустушуу ва пешгирии бастани сӯрохиҳои хурд дар хокҳои арголӣ, диққат ба нуқтаҳои пеш аз харидани навори оборӣи дрип зарур аст, зеро бастани хусусияти нейтралӣ дар навир метавонад ба марги наботот дар наздикии он минтақа ва бекоршавии маблағи сарфшудаи боридан оварда расонад.</p>\n\n<h2>Саволҳои маъмул (FAQ)</h2>\n<h3>Оё фарқияти навъҳои отавии ғундорӣ ва ҳубубӣ дар миқдори бӯно таъсир менамояд?</h3>\n<p>Бале. Навъҳои ҳубубӣ одатан донҳои бузургтар доранд ва дар як килограмм шумораи донҳои камтар нисбат ба навъҳои отавии дони хурд доранд. Бинобар ин, барои расидан ба зичии якхелаи наботот, вазни бӯнои зарурӣ тағйир меёбад. Ҳамеша зичии дон (DWT)-ро дар бастаи бӯно санҷед.</p>\n\n<h3>Беҳтарин вақти боридани отав барои баромадан аз оборӣи буқъадор кист?</h3>\n<p>Дар нимаҳои шимолӣ аз миёна то охири моҳи баҳор; дар минтақаҳои ҷанубӣ аз моҳи зимистон то тирамоҳ. Барномаи вақти боридан бояд чунин бошад, ки дар марҳалаҳои ҳассоси рушд (30 то 45 рӯз пас аз боридан), манбаъҳои кофии об ва нуқсӣ (нур) барои наботот таъмин шаванд, то аз фишори ҳароратӣ дар оғози рушд пешгирӣ карда шавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-سورگوم-در-هکتار-راهنمای-جامع-جزئیات-فنی.webp" alt="مقدار بذر سورگوم در هکتار: راهنمای جامع - تصویر 3"/><figcaption>norma kalandon bar hektar ziraat sorghum</figcaption></figure>\n\n<h3>Oyob mi tova miho ziraat sorghum ba miqdori kalandoni makkho\' beshanand?</h3>\n<p>Ne, alii ki ommo omonand, val ba inu dala\' va imkoni nishodan farq kardanand. Kalandi sorghum odatan zohira tar va pakh kardan narm tarand. Istifoda shudani adadi makkho\' me monand kalandon ba zaodan (Overseeding) va shikast ziraat bovar shad. <a href="https://navar-abyari.ir/melon-seed-quantity-per-hectare-planting-density-table/">Miqdori kalandi hamsom bar hektar</a> Omona tashdik koshandand, ki har navi ziraat bor asosi tahlili xoshi kaloni munhasib shavad.</p>\n\n<h2>Khulosah</h2>\n<p>Muayyani daqiq <strong>Miqdori kalandi sorghum bar hektar</strong> Ин раванди динамикӣ аст, ки вобаста ба мақсади парвариш (шурӯғ ё дон), намуди хок, иқлим ва системаи обёрӣ тағйир меёбад. истифодаи системаи навардӣ дар банди потенсиали самаранокиро зиёд мекунад, аммо танҳо дар ҳолате ки зичии нишона бо тавононии решаҳо ва зарурияти об мувофиқат кунад. Хатои дар зичии нишона сармоягузории шуморо ба хатар доред. Маслиҳати ниҳоӣ ин аст, ки аз соли аввал маълумотро сабт кунед; шумораи нишона дар метр, масофаи нишона, ва дарсади шунбид. Ин маълумот дар соли оянда ба шумо кӯмак мекунад, ки миқдори зарурати донро дақиқтар ҳисоб кунед. Кирдеҳии дақиқ, ҳамон чизест, ки ояндаро равшантар менамояд ва самаранокии иқтисодиро кафолат медиҳад.</p>\n<p><strong>Маводи марбутӣ:</strong> <a href="https://navar-abyari.ir/%d9%85%db%8c%d8%b2%d8%a7%d9%86-%d8%a8%d8%b1%d8%af%d8%a7%d8%b4%d8%aa-%d8%b0%d8%b1%d8%aa-%d8%b9%d9%84%d9%88%d9%81%d9%87%d8%a7%db%8c-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Ҳосили чурчаки шурӯғӣ дар гектар: Раҳнамони комил оид ба зиёд кардани ҳосил ва фоида</a></p>','Микдори тоҷи соргоҳо дар як гектар: Роҳнамои пурра','Интихоби дурусти миқдори боди сорго дар ҳектар ба назардошти омилҳои иқлӣ, намуди кишоварзӣ ва системаи обёрӣ вобаста аст. Ин мақола бо диққати беш аз ҳама ба обёрии тақтиқӣ ва намуди полосавӣ роҳнамои пурра барои муайян кардани зичии ҷамъоварӣ ва баланд бардоштани самаранокии иқтисодӣ пешниҳод мекунад. Бо таҳлили ҷадвалҳои фосилагиригӣ ва нуқтаҳои амалӣ, шумо мефаҳмед, ки чӣ тавр метавонед аз хароҷоти бефоидаи манбаъҳо пешгирӣ карда, ба ҳадди акс истеҳсоми олвӣ донӣ расед. Ин дастур барои деҳқонони касбӣ, ки ҷустуҷӯи баланд бардоштани сатҳи кишоварзии худро пеш мегиранд, сохта шудааст.','publish','closed','closed','mikdori-toji-sorgo-dar-yak-gektar-rahnamoi-porra',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
