INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<p>Интихоби дуруст <strong>Фавои навбатҳои тип дар парҳези аспаргус (марчубоҳ)</strong> Яке муҳимтарин нуктаҳои андешадан дар тарҳрезии системаҳои оборӣ қатқатрӣ мебошад. Аспаргус (Marҷубоҳ) гиёҳи доимӣ ва бардор аст, ки решаҳои чуқур ва васеъ дорад ва ба идоракунии дақиқи ҳарорати хок ниёз дорад. Истиноди навбатҳои тип ба ҷои хати навбатҳои классикӣ, бо сабаби арзиш паст ва баландии интихобот, бешубҳа маъруф шудааст; аммо муайян кардани фавои дурусти ин навбатҳо аз сафҳои гиёҳ, мустақиман ба самаранокии, сифати чӯбҳои аспаргус ва пешгирии шиддати об таъсир мерасонад. Дар ин роҳнамо, мо ба баррасии меъёрҳои илмӣ ва таҷрибавӣ барои муайян кардани ин фаво муносиб мешавем.</p><h2>Муҳимияти идоракунии фавои навбатҳои тип дар парҳези аспаргус</h2><p>Аспаргус барои захираи энергия ва рушди дигарон ба решаҳои худ (Ризомҳо) вобаста аст. Агар фавои навбатҳои тип аз сафҳои корфазл хеле дур бошад, намӣ ба минтачаи решаҳои асосӣ намерасад ва гиёҳ шиддат мекунад. Аз тарафи дигар, фавои хеле наздик метавонад ба хатони манбаъҳо ва рӯидаҳи зиёдатии решаҳои сатҳӣ дар минтачаи оборӣ оварда расонад, ки идоракуниаш душвортар аст. Бинобар ин, ҳадаф расидани намӣ ба ҳамаи фаъоли реша дар чуқурӣ ва андозаи мувофиқ мебошад.</p><p>Омили зиёде ба муайян кардани <a href="https://navar-abyari.ir/miqdori-obdihiyi-novori-tipii-baroi-obeyri/">миқдори оборишудаи навбатҳои тип барои оборӣ</a> ва дар охир ба фавои навбатҳо аз сафҳо таъсир мерасонанд. Намуди хок, миқдори баронҳо ва ҳарорати минтақа аз шумораи ин омор мебошанд. Дар хокҳои гилӣ, ки нафузи камтар доранд, метавонад ниёз ба фавои камтар бошад, то намӣ саросимӣ дар минтачаи реша паҳн шавад, дар ҳол, ки дар хокҳои шабаҳӣ бо нафузи баланд, фаво метавонад каме зиёдтар бошад, то хатони орқулаи чуқур кам карда шавад.</p><h2>Стандарти тавсияшуда барои фосилаи пайи (тиби) нопи</h2><p>Асоси таҳқиқот ва таҷрибаҳои амалӣ дар парҳези шурӯрӣ, андозаҳои зерини стандартӣ пешниҳод мешаванд, ки дар тарроҳии система бояд ба назар гирифта шаванд:</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-مارچوبه-استانداردهای-توصیهشده-تصویر-شاخص.webp" alt="فاصله نوار تیپ در کشت مارچوبه: استانداردهای توصیه‌شده - تصویر 1"/><figcaption>фосилаи пайи тиби чидиши сафи парҳез шурӯрӣ</figcaption></figure><ul><li><strong>Фосилаи пайи тиби аз маркази саф:</strong> Одатан байни 30 то 40 сантиметр тавсия дода мешавад. Ин фосила ғолибтарин минтақа барои ҷойгиршавии решаҳои фаъоли шурӯрӣ мебошад.</li><li><strong>Фосилаи байни ду пай:</strong> Дар сурати истифодаи ду пай дар ҳар саф, фосилаи пайи чап ва рост бояд бунёд шуда бошад, ки пурраи намӣ сарпӯшӣ бошад. Одатан фосилаи байни ду пай тақрибан 60 то 80 сантиметр (бо ҳисоб кардани ангуштаи саф) ҳисоб карда мешавад.</li><li><strong>Чоқи гузарондани пай:</strong> Капсидаи (типи) лентаро бояд дар чуқури 10 то 15 сантиметр зери ояни замин насб кард, то ки муқовимати он ба нурҳои UV ва осебҳои механикӣ бошад ва бод ва тарик ба мустақиман ба ҳудуди решаҳо расад.</li></ul><p>Дар аксар ҳолатҳо, умуман, <strong>Фосилаи 35 сантиметрӣ</strong> аз маркази сатҳи қаротуба ҳамчун нуқтаи оптималӣ ба назар гирифта мешавад. Ин фосила барои таносули рехтани решаҳо ва камтарин хориши об таъмин мекунад.</p><h2>Нуқтаҳои амалӣ дар насб ва танзими фосилаи капида (лента)</h2><p>Насби дурусти капидаи (лента) ҳамзамон бо сатҳҳои қаротуба талаботи дақиқ дорад. Дар марҳилаи кишт бо шакли баста (Beds), роҳи гузашти капида бояд аз пеш муайян шавад. Агар бастаҳо бо шакли каҷмон (қаъуӣ) сохта шуда бошанд, капидаҳо бояд дар шиккарҳои канории бастаҳо ҷойгир шаванд.</p><ol><li><strong>Шарҳи чарогиҳои капида (лента):</strong> Аз чарогиҳои капида (лентаро) дар худи лӯлаи асосӣ ё дароз давомкор (continuous) худдорӣ кунед. Капида бояд бе чарогиҳо, вале зери фишори нозуки замин бошад, то ки ҷояшро тағир надиҳад.</li><li><strong>Тести фишор:</strong> Пеш аз пӯшидани пурраи хок, системаро бо фишори корӣ тест кунед, то боварии ҳосили нашавии дар пайвастҳо даманд.</li><li><strong>Мутолиқкунӣ кунҷкор:</strong> Агар шулои замин зиёд бошад, фосилаи риштаи тӯб метавонад лозим ба танзими махсустар бошад, то пешгирии обёркунии нокофии дар анҷоми шуло шаванд. Дар ин ҳолат истифодаи шири идоракунии фишор дар анҷоми ришта зарур аст.</li></ol><p>Барои фаҳмиши беҳтари тарзи ҷойгиршавии физикии риштаҳо, шумо метавонед <a href="https://navar-abyari.ir/drip-irrigation-tape-installation-steps-ariq/">Марҳилаҳои насби риштаи тӯбқатонӣ</a> ро хонед. Ин марҳилаҳо аз ҳамоҳангсозии сатҳи замин, сохтани шитоб мувофиқ барои ришта ва пайвастани дуруст ба лӯлаи асосӣ иборат аст.</p><h2>Таъсири фосилаи ришта ба сифат ва миқдори истеҳсоли машӯби</h2><p>Ориёнтатсияи барққутии тасма бо сабаби консентратсияи намӣ дар минтаҷаи решаҳо барои вобулдидани тӯлҳои равишии равонакҳои равонак мусоидат мекунад. Агар фосилаи тасма аз қатор зиёд бошад, ҷуворот маҷбур мешавад, ки энергияро барои пуррашавии решаҳои сӯлавӣ ба самти берун аз минтаҷаи ороишӣ харҷ кунад, ки ин боиси оҳиста кардани рӯшани ҷисми асосӣ мегардад. Дар натиҷа, <strong>Фосилаи тасмаи ориёнтатсионӣ дар киштҳои равонак</strong> бо назардошти имконияти ҷозибиши решаҳо оптимизатсия карда мешавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-مارچوبه-استانداردهای-توصیهشده-کاربرد-عملی.webp" alt="فاصله نوار تیپ در کشت مارچوبه: استانداردهای توصیه‌شده - تصویر 2"/><figcaption>drip tape spacing row layout crop равонак</figcaption></figure><p>Барои муқоиса бо дигар сабзавот, идоракунии фосила дар киштҳои zichӣ чун ниққори саф метавонад намунаи монанд дошта бошад. Барои шиносоӣ бо талаботи ороиши дигар маҳсулот, мақола <a href="https://navar-abyari.ir/white-onion-yield-per-hectare-iraq/">меъёри ҷамъовии ниққори саф дар гектар</a> ро баррасӣ кунед. Гарчанде ки равонак ҷувори доимӣ аст, принсипҳои ороиши тасмаӣ дар ҳамаи ин маҳсулот умумӣ буда, мақсади асосӣ идоракунии намӣ бе талафоти он мебошад.</p><h2>Саволҳои муқаррарӣ (FAQ) дар бораи фосилаи тасмаи ориёнтатсионӣ дар равонак</h2><p><strong>1. Оё дар ҳар сатҳи сабзи палд аз ҷойи ду нақраи лавҳаҳои дрип, метавон метавонад яке истифода барад?</strong><br>Бале, дар баъзе системаҳо лавҳаи миёна истифода мешавад, аммо дар сабзи палд, ки сатҳҳо васеътаранд ва решаҳо ҷудо шудаанд, истифодаи ду лавҳа (яке дар тарафи чап ва яке дар тарафи рост) пӯшиши баробартар меорад. Дар ин ҳолат масоҳати ҳар лавҳа аз марказ 30-35 сантиметр мебошад.</p><p><strong>2. Лавҳаҳои дрипро дар сатҳҳои ҳамсоя бояд бо кадом масоҳат аз ҳам ҷудо кунем?</strong><br>Масоҳати сатҳҳои ғаллаи сабзи палд одатан 1.5 то 2 метр аст. Лавҳаҳо дар сатҳҳои паҳлӯии ҳар хат ҷой мегиранд. Агар системаи шумо лавҳаҳои пайвастшуда дошта бошад, бояд роҳи каналҳоро чунин тарҳ кунед, ки масоҳати стандартии дохилии ҳар сатҳ нигоҳ дошта шавад.</p><p><strong>3. Оё намуди тухм ё қуллаи сабзи палд ба масоҳати лавҳаи дрип таъсир мерасонад?</strong><br>Не, бебосита, аммо андозаи хат ва зичии ғалласозӣ (тедоди қуллаҳо дар ҳар метри хат) муҳим аст. Агар зичии ғалласозӣ хеле баланд бошад, масоҳати лавҳа аз маркази сатҳ бояд каме бештар бошад, то аз хариду шудани лавҳа тавассути қуллаҳои иловагӣ пешгирӣ шавад. Барои огоҳӣ аз зичии ғалласозии маҳсулоти монанд, шумо метавонед миқдори тухмро дар ҳектарро барои маҳсулоти дигар омӯхта, нисбатро фаҳмед.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-مارچوبه-استانداردهای-توصیهشده-جزئیات-فنی.webp" alt="فاصله نوار تیپ در کشت مارچوبه: استانداردهای توصیه‌شده - تصویر 3"/><figcaption>drip tape spacing row layout crop марҷубоҳе</figcaption></figure><p><strong>4. Дар сатҳҳои баъд аз ғалласозӣ дар чӣ ҳолат лозим аст, ки масоҳати лавҳаи дрипро тағйир диҳем?</strong><br>Бо зиёд шудан син соли чӯби кӯрҳӯш (пас аз соли дуюм), решаҳо васеъ мешаванд. Дар ин ҳолат, агар имкони ҳаракат додани наворҳо вуҷуд дошта бошад, масофаро то 45-50 сантиметр зиёд кардан мумкин аст, то ки ин бо инкишофи тӯпи реша мутобиқ бошад. Агар наворҳо собит бошанд, бояд бо зиёд кардани суръати обёрӣ ҷуброн карда шавад.</p><h2>Хулоса</h2><p>Меъёри асосӣ дар интихоб <strong>Масофаи наворҳо дар парези кӯрҳӯш</strong>, дастрасии оптималии реша ба намӣ аст. Масофаи стандардии 30 то 40 сантиметр аз маркази кӯл (палас), нуқтаи оғози хуб барои аксари шароити иқлимӣ ва хокӣ мебошад. Бо риоя кардани нукоти мусоид ва танзими фишор, метавон самаранокии системаи обёриро зиёд кард ва аз стресси обӣ ин ниҳоди ҳассосро муҳофизат намуд. ҳамیشа тавсия дода мешавад, ки пеш аз амалиёти васеъ, ин масофаҳоро дар қисми хурди замин санҷида, содиротро назорат кунед.</p>\n<p><strong>Маводуи вобаста:</strong> <a href="https://navar-abyari.ir/%d9%85%d9%82%d8%af%d8%a7%d8%b1-%d8%a8%d8%b0%d8%b1-%d8%b0%d8%b1%d8%aa-%d8%b9%d9%84%d9%88%d9%81%d9%87-%d8%a7%db%8c-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Ҳаҷми бӯри чигити озуворӣ дар як гектар чӣ қадар аст?</a></p>','Фосилаи шитори бори кунҷичи мурчӯб: Стандартҳои тавсияшуда','Шиносоӣ бо беҳтарин масофаи ҷавҳи паймонӣ дар парҳези лахтак, омилҳои таъсирбахш ба интихоби масофа, нуқтаҳои амалӣ оид ба насб ва ҷавоб ба саволҳои маъмул. Раҳнамоии пурра барои деҳқонон барои баланд бардоштани маҳсулнокӣ.','publish','closed','closed','fosila-i-chora-i-konichi-i-murchob',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
