SET @source_post_id=(SELECT post_id FROM `ha_postmeta` WHERE meta_key='_navar_queue_item_id' AND meta_value='article-content-queue:crop-217' LIMIT 1);
SET @translation_id=(SELECT post_id FROM `ha_postmeta` WHERE meta_key='_navar_translation_queue_key' AND meta_value='article-translation:crop-217:en-US' LIMIT 1);
SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='tef-film-stripe-spacing-lettuce-cultivation-recommended-standards' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @translation_id=COALESCE(@translation_id,IF(@source_post_id IS NOT NULL AND @slug_conflict IS NULL,LAST_INSERT_ID(),NULL));
COMMIT;

